const yearQuestions = [{"id":200000,"topic":"year-0","title":"秦による中国統一","year":-221,"era":"古代","q":"始皇帝が中国を統一した年は？","answer":"前221年","aliases":["前221年","前221","紀元前221年","紀元前221","-221","BC221","221BC","BCE221","221BCE"],"ex":"前221年。秦王政が戦国諸国を統一して始皇帝を称した。郡県制や文字・度量衡の統一も結びつけよう。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200001,"topic":"year-1","title":"劉邦の皇帝即位","year":-202,"era":"古代","q":"劉邦が漢の皇帝となった年は？","answer":"前202年","aliases":["前202年","前202","紀元前202年","紀元前202","-202","BC202","202BC","BCE202","202BCE"],"ex":"前202年。項羽との争いを制した劉邦が高祖となった。漢王となった時点と、皇帝即位を区別する。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200002,"topic":"year-2","title":"周の東遷","year":-770,"era":"古代","q":"周が洛邑へ東遷した年は？","answer":"前770年","aliases":["前770年","前770","紀元前770年","紀元前770","-770","BC770","770BC","BCE770","770BCE"],"ex":"前770年。以後を東周と呼ぶ。春秋・戦国時代の諸侯の争いへとつながる。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200003,"topic":"year-3","title":"蔡倫の製紙法改良の報告","year":105,"era":"古代","q":"蔡倫が製紙法の改良を後漢の皇帝に報告した年は？","answer":"105年","aliases":["105年","105","西暦105","西暦105年","AD105","105AD","CE105","105CE"],"ex":"105年。紙はそれ以前にも存在した。この年を紙そのものの発明年と断定しない。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"標準"},{"id":200004,"topic":"year-4","title":"黄巾の乱","year":184,"era":"古代","q":"張角らによる黄巾の乱が起きた年は？","answer":"184年","aliases":["184年","184","西暦184","西暦184年","AD184","184AD","CE184","184CE"],"ex":"184年。後漢末の大規模な反乱。地方軍事勢力の台頭や三国分立への過程と結びつく。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200005,"topic":"year-5","title":"魏の成立","year":220,"era":"古代","q":"曹丕が後漢に代わって魏を建てた年は？","answer":"220年","aliases":["220年","220","西暦220","西暦220年","AD220","220AD","CE220","220CE"],"ex":"220年。曹丕は献帝から禅譲を受けた。後の北魏とは別の王朝である。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200006,"topic":"year-6","title":"西晋の中国統一","year":280,"era":"古代","q":"西晋が呉を滅ぼして中国を統一した年は？","answer":"280年","aliases":["280年","280","西暦280","西暦280年","AD280","280AD","CE280","280CE"],"ex":"280年。司馬炎の西晋による統一。後に八王の乱などで再び分裂へ向かった。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200007,"topic":"year-7","title":"東晋の成立","year":317,"era":"古代","q":"司馬睿による東晋の成立は何年？","answer":"317年","aliases":["317年","317","西暦317","西暦317年","AD317","317AD","CE317","317CE"],"ex":"317年。都は建康。北方からの人口移動や江南開発とも関連する。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200008,"topic":"year-8","title":"北魏の洛陽遷都","year":494,"era":"古代","q":"北魏の孝文帝が洛陽へ遷都した年は？","answer":"494年","aliases":["494年","494","西暦494","西暦494年","AD494","494AD","CE494","494CE"],"ex":"494年。平城から洛陽へ遷都し、漢化政策を進めた。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200009,"topic":"year-9","title":"隋の中国再統一","year":589,"era":"中世","q":"隋の文帝が陳を滅ぼして中国を再統一した年は？","answer":"589年","aliases":["589年","589","西暦589","西暦589年","AD589","589AD","CE589","589CE"],"ex":"589年。南北朝の分裂を終わらせた。唐の建国とは年が異なる。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200010,"topic":"year-10","title":"唐の成立","year":618,"era":"中世","q":"李淵が唐を建てた年は？","answer":"618年","aliases":["618年","618","西暦618","西暦618年","AD618","618AD","CE618","618CE"],"ex":"618年。李淵は高祖となり、長安を都とした。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200011,"topic":"year-11","title":"タラス河畔の戦い","year":751,"era":"中世","q":"唐軍とアッバース朝側がタラス河畔で戦った年は？","answer":"751年","aliases":["751年","751","西暦751","西暦751年","AD751","751AD","CE751","751CE"],"ex":"751年。中央アジアでの戦い。製紙技術の伝播を、この戦いだけで説明しないよう注意する。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200012,"topic":"year-12","title":"鑑真の来日","year":753,"era":"中世","q":"唐の僧・鑑真が来日した年は？","answer":"753年","aliases":["753年","753","西暦753","西暦753年","AD753","753AD","CE753","753CE"],"ex":"753年。複数回の渡航失敗の後に来日し、日本で戒律や授戒制度の整備に関わった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"標準"},{"id":200013,"topic":"year-13","title":"安史の乱の開始","year":755,"era":"中世","q":"安禄山らによる安史の乱が始まった年は？","answer":"755年","aliases":["755年","755","西暦755","西暦755年","AD755","755AD","CE755","755CE"],"ex":"755年。反乱は763年まで続いた。開始年と終結年を区別する。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200014,"topic":"year-14","title":"両税法の導入","year":780,"era":"中世","q":"唐で両税法が導入された年は？","answer":"780年","aliases":["780年","780","西暦780","西暦780年","AD780","780AD","CE780","780CE"],"ex":"780年。徳宗の時代、楊炎の建議によって夏と秋に徴税する制度が導入された。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200015,"topic":"year-15","title":"北宋の成立","year":960,"era":"中世","q":"趙匡胤が北宋を建てた年は？","answer":"960年","aliases":["960年","960","西暦960","西暦960年","AD960","960AD","CE960","960CE"],"ex":"960年。趙匡胤は太祖となり、文治主義を進めた。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200016,"topic":"year-16","title":"西夏での皇帝称号","year":1038,"era":"中世","q":"李元昊が西夏で皇帝を称した年は？","answer":"1038年","aliases":["1038年","1038","西暦1038","西暦1038年","AD1038","1038AD","CE1038","1038CE"],"ex":"1038年。タングートの国家。宋・遼・金との位置関係も押さえよう。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"標準"},{"id":200017,"topic":"year-17","title":"王安石の新法","year":1069,"era":"中世","q":"北宋で王安石の新法が始まった年は？","answer":"1069年","aliases":["1069年","1069","西暦1069","西暦1069年","AD1069","1069AD","CE1069","1069CE"],"ex":"1069年。神宗期に財政や軍事の強化を目指した改革。旧法党との政治対立を招いた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"標準"},{"id":200018,"topic":"year-18","title":"金の成立","year":1115,"era":"中世","q":"完顔阿骨打が金を建てた年は？","answer":"1115年","aliases":["1115年","1115","西暦1115","西暦1115年","AD1115","1115AD","CE1115","1115CE"],"ex":"1115年。女真の王朝。遼を滅ぼし、続いて北宋を倒した。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200019,"topic":"year-19","title":"靖康の変","year":1127,"era":"中世","q":"靖康の変によって北宋が滅亡した年は？","answer":"1127年","aliases":["1127年","1127","西暦1127","西暦1127年","AD1127","1127AD","CE1127","1127CE"],"ex":"1127年。徽宗・欽宗が金に連行され、趙構が南宋を再建した。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200020,"topic":"year-20","title":"チンギス＝ハンの推戴","year":1206,"era":"中世","q":"テムジンがチンギス＝ハンに推戴された年は？","answer":"1206年","aliases":["1206年","1206","西暦1206","西暦1206年","AD1206","1206AD","CE1206","1206CE"],"ex":"1206年。モンゴル高原の統合と帝国拡大の出発点となった。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200021,"topic":"year-21","title":"元の国号制定","year":1271,"era":"中世","q":"フビライが国号を元と定めた年は？","answer":"1271年","aliases":["1271年","1271","西暦1271","西暦1271年","AD1271","1271AD","CE1271","1271CE"],"ex":"1271年。南宋滅亡の1279年とは異なる。国号制定と中国全土の征服を分けて覚える。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200022,"topic":"year-22","title":"南宋の滅亡","year":1279,"era":"中世","q":"元によって南宋が滅亡した年は？","answer":"1279年","aliases":["1279年","1279","西暦1279","西暦1279年","AD1279","1279AD","CE1279","1279CE"],"ex":"1279年。フビライによる元の国号制定は1271年。両者を区別しよう。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200023,"topic":"year-23","title":"明の成立","year":1368,"era":"中世","q":"朱元璋が明を建てた年は？","answer":"1368年","aliases":["1368年","1368","西暦1368","西暦1368年","AD1368","1368AD","CE1368","1368CE"],"ex":"1368年。南京で即位して洪武帝となった。元の勢力は北方へ退いた。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200024,"topic":"year-24","title":"明の丞相廃止","year":1380,"era":"中世","q":"洪武帝が胡惟庸の事件を機に丞相を廃した年は？","answer":"1380年","aliases":["1380年","1380","西暦1380","西暦1380年","AD1380","1380AD","CE1380","1380CE"],"ex":"1380年。六部を皇帝に直属させ、皇帝権力を強化した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"標準"},{"id":200025,"topic":"year-25","title":"鄭和の第1回航海","year":1405,"era":"中世","q":"鄭和の最初の南海遠征が始まった年は？","answer":"1405年","aliases":["1405年","1405","西暦1405","西暦1405年","AD1405","1405AD","CE1405","1405CE"],"ex":"1405年。永楽帝の命による航海。最後の遠征が帰着する1433年と区別する。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200026,"topic":"year-26","title":"明の北京遷都","year":1421,"era":"中世","q":"永楽帝が正式に北京へ遷都した年は？","answer":"1421年","aliases":["1421年","1421","西暦1421","西暦1421年","AD1421","1421AD","CE1421","1421CE"],"ex":"1421年。南京から北京へ首都を移した。北方への軍事対応とも関わる。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200027,"topic":"year-27","title":"土木の変","year":1449,"era":"中世","q":"明の正統帝がオイラトに捕らえられた土木の変は何年？","answer":"1449年","aliases":["1449年","1449","西暦1449","西暦1449年","AD1449","1449AD","CE1449","1449CE"],"ex":"1449年。エセンが率いるオイラトとの戦いで起きた事件。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"標準"},{"id":200028,"topic":"year-28","title":"後金の成立","year":1616,"era":"近世","q":"ヌルハチが後金を建てた年は？","answer":"1616年","aliases":["1616年","1616","西暦1616","西暦1616年","AD1616","1616AD","CE1616","1616CE"],"ex":"1616年。八旗を基盤とする国家形成。清への国号変更は1636年である。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200029,"topic":"year-29","title":"清への国号変更","year":1636,"era":"近世","q":"ホンタイジが国号を清へ改めた年は？","answer":"1636年","aliases":["1636年","1636","西暦1636","西暦1636年","AD1636","1636AD","CE1636","1636CE"],"ex":"1636年。後金の建国は1616年、清の北京入城は1644年。三つの年を整理しよう。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200030,"topic":"year-30","title":"清の北京入城","year":1644,"era":"近世","q":"清軍が北京に入城した年は？","answer":"1644年","aliases":["1644年","1644","西暦1644","西暦1644年","AD1644","1644AD","CE1644","1644CE"],"ex":"1644年。李自成の軍によって北京の明朝が倒れた後、清軍が入城した。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200031,"topic":"year-31","title":"ネルチンスク条約","year":1689,"era":"近世","q":"清とロシアがネルチンスク条約を結んだ年は？","answer":"1689年","aliases":["1689年","1689","西暦1689","西暦1689年","AD1689","1689AD","CE1689","1689CE"],"ex":"1689年。康熙帝期の国境をめぐる外交。19世紀のアイグン条約と区別する。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"標準"},{"id":200032,"topic":"year-32","title":"南京条約","year":1842,"era":"近代","q":"アヘン戦争を終結させた南京条約が結ばれた年は？","answer":"1842年","aliases":["1842年","1842","西暦1842","西暦1842年","AD1842","1842AD","CE1842","1842CE"],"ex":"1842年。清は香港島の割譲や五港開港などを認めた。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200033,"topic":"year-33","title":"下関条約","year":1895,"era":"近代","q":"日清戦争を終結させた下関条約が結ばれた年は？","answer":"1895年","aliases":["1895年","1895","西暦1895","西暦1895年","AD1895","1895AD","CE1895","1895CE"],"ex":"1895年。日清戦争自体は1894年に始まった。条約では台湾などの割譲が定められた。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200034,"topic":"year-34","title":"戊戌の変法","year":1898,"era":"近代","q":"康有為・梁啓超らが戊戌の変法を進めた年は？","answer":"1898年","aliases":["1898年","1898","西暦1898","西暦1898年","AD1898","1898AD","CE1898","1898CE"],"ex":"1898年。光緒帝のもとでの改革は、西太后側による政変で挫折した。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200035,"topic":"year-35","title":"辛亥革命の勃発","year":1911,"era":"近代","q":"武昌蜂起に始まる辛亥革命が起きた年は？","answer":"1911年","aliases":["1911年","1911","西暦1911","西暦1911年","AD1911","1911AD","CE1911","1911CE"],"ex":"1911年。中華民国成立や清帝退位の1912年と区別する。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200036,"topic":"year-36","title":"五・四運動","year":1919,"era":"近代","q":"中国で五・四運動が起きた年は？","answer":"1919年","aliases":["1919年","1919","西暦1919","西暦1919年","AD1919","1919AD","CE1919","1919CE"],"ex":"1919年。山東権益の処理などに抗議する学生運動から広がった。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200037,"topic":"year-37","title":"盧溝橋事件","year":1937,"era":"近代","q":"日中戦争全面化の契機となった盧溝橋事件は何年？","answer":"1937年","aliases":["1937年","1937","西暦1937","西暦1937年","AD1937","1937AD","CE1937","1937CE"],"ex":"1937年。1931年の柳条湖事件と区別して覚えよう。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200038,"topic":"year-38","title":"中華人民共和国の成立","year":1949,"era":"現代","q":"中華人民共和国が成立した年は？","answer":"1949年","aliases":["1949年","1949","西暦1949","西暦1949年","AD1949","1949AD","CE1949","1949CE"],"ex":"1949年。毛沢東が北京で成立を宣言した。国共内戦と海峡両岸の分断に結びつく。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200039,"topic":"year-39","title":"朝鮮戦争の開始","year":1950,"era":"現代","q":"朝鮮戦争が始まった年は？","answer":"1950年","aliases":["1950年","1950","西暦1950","西暦1950年","AD1950","1950AD","CE1950","1950CE"],"ex":"1950年。北朝鮮軍の南進により始まった。1953年の休戦と区別する。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200040,"topic":"year-40","title":"朝鮮戦争の休戦","year":1953,"era":"現代","q":"朝鮮戦争の休戦協定が結ばれた年は？","answer":"1953年","aliases":["1953年","1953","西暦1953","西暦1953年","AD1953","1953AD","CE1953","1953CE"],"ex":"1953年。休戦協定は平和条約とは異なり、戦闘停止の枠組みを定めた。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200041,"topic":"year-41","title":"渤海の成立","year":698,"era":"中世","q":"大祚栄が渤海を建てた年は？","answer":"698年","aliases":["698年","698","西暦698","西暦698年","AD698","698AD","CE698","698CE"],"ex":"698年。旧高句麗領の一部などを基盤とした国家で、日本とも外交関係を結んだ。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200042,"topic":"year-42","title":"高麗の成立","year":918,"era":"中世","q":"王建が高麗を建てた年は？","answer":"918年","aliases":["918年","918","西暦918","西暦918年","AD918","918AD","CE918","918CE"],"ex":"918年。後三国統一の936年とは区別する。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200043,"topic":"year-43","title":"金属活字本『直指』","year":1377,"era":"中世","q":"現存最古の金属活字印刷本とされる『直指』が印刷された年は？","answer":"1377年","aliases":["1377年","1377","西暦1377","西暦1377年","AD1377","1377AD","CE1377","1377CE"],"ex":"1377年。高麗の印刷文化を示す。グーテンベルク以前の印刷史を理解する手がかり。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"標準"},{"id":200044,"topic":"year-44","title":"朝鮮王朝の成立","year":1392,"era":"中世","q":"李成桂が朝鮮王朝を建てた年は？","answer":"1392年","aliases":["1392年","1392","西暦1392","西暦1392年","AD1392","1392AD","CE1392","1392CE"],"ex":"1392年。高麗に代わる王朝として成立し、朱子学を重視した。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200045,"topic":"year-45","title":"訓民正音の公布","year":1446,"era":"中世","q":"世宗のもとで訓民正音が公布された年は？","answer":"1446年","aliases":["1446年","1446","西暦1446","西暦1446年","AD1446","1446AD","CE1446","1446CE"],"ex":"1446年。文字の完成とされる1443年と、公布年を区別する。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}],"region":"east","level":"基礎"},{"id":200046,"topic":"year-46","title":"ハギア＝ソフィアの完成","year":537,"era":"中世","q":"ユスティニアヌス帝が再建したハギア＝ソフィア大聖堂が完成した年は？","answer":"537年","aliases":["537年","537","西暦537","西暦537年","AD537","537AD","CE537","537CE"],"ex":"537年。532年に始まった再建事業が完成した。ビザンツ建築を代表する。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}],"region":"culture","level":"基礎"},{"id":200047,"topic":"year-47","title":"ルターの九十五か条の論題","year":1517,"era":"近世","q":"ルターが九十五か条の論題を示した年は？","answer":"1517年","aliases":["1517年","1517","西暦1517","西暦1517年","AD1517","1517AD","CE1517","1517CE"],"ex":"1517年。贖宥状をめぐる批判が宗教改革の出発点となった。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}],"region":"europe","level":"基礎"},{"id":200048,"topic":"year-48","title":"コペルニクスの著作","year":1543,"era":"近世","q":"コペルニクスの『天球の回転について』が刊行された年は？","answer":"1543年","aliases":["1543年","1543","西暦1543","西暦1543年","AD1543","1543AD","CE1543","1543CE"],"ex":"1543年。太陽を中心とする惑星体系を論じた。後のケプラーやガリレイとつなげよう。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}],"region":"culture","level":"基礎"},{"id":200049,"topic":"year-49","title":"ウェストファリア条約","year":1648,"era":"近世","q":"三十年戦争を終結させたウェストファリア条約は何年？","answer":"1648年","aliases":["1648年","1648","西暦1648","西暦1648年","AD1648","1648AD","CE1648","1648CE"],"ex":"1648年。ヨーロッパの宗教・政治秩序を考える重要な講和である。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}],"region":"europe","level":"基礎"},{"id":200050,"topic":"year-50","title":"ニュートンの著作","year":1687,"era":"近世","q":"ニュートンの『プリンキピア』が刊行された年は？","answer":"1687年","aliases":["1687年","1687","西暦1687","西暦1687年","AD1687","1687AD","CE1687","1687CE"],"ex":"1687年。運動法則や万有引力を体系化した科学革命の重要な著作。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}],"region":"culture","level":"基礎"},{"id":200051,"topic":"year-51","title":"アメリカ独立宣言","year":1776,"era":"近世","q":"アメリカ独立宣言が採択された年は？","answer":"1776年","aliases":["1776年","1776","西暦1776","西暦1776年","AD1776","1776AD","CE1776","1776CE"],"ex":"1776年。独立戦争開始の1775年や、パリ条約による独立承認の1783年と区別する。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}],"region":"europe","level":"基礎"},{"id":200052,"topic":"year-52","title":"フランス革命の開始","year":1789,"era":"近世","q":"バスティーユ襲撃などで始まるフランス革命は何年？","answer":"1789年","aliases":["1789年","1789","西暦1789","西暦1789年","AD1789","1789AD","CE1789","1789CE"],"ex":"1789年。絶対王政と身分制を揺るがした。人権宣言も同年に採択された。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}],"region":"europe","level":"基礎"},{"id":200053,"topic":"year-53","title":"ベートーヴェンの第九","year":1824,"era":"近代","q":"ベートーヴェンの第九交響曲が初演された年は？","answer":"1824年","aliases":["1824年","1824","西暦1824","西暦1824年","AD1824","1824AD","CE1824","1824CE"],"ex":"1824年。終楽章に独唱と合唱を導入し、シラーの詩を用いた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}],"region":"culture","level":"標準"},{"id":200054,"topic":"year-54","title":"第1回印象派展","year":1874,"era":"近代","q":"モネらによる第1回印象派展が開かれた年は？","answer":"1874年","aliases":["1874年","1874","西暦1874","西暦1874年","AD1874","1874AD","CE1874","1874CE"],"ex":"1874年。公式サロンの外で共同展を開き、新しい絵画表現を提示した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}],"region":"culture","level":"標準"},{"id":200055,"topic":"year-55","title":"第一次世界大戦の開始","year":1914,"era":"近代","q":"第一次世界大戦が始まった年は？","answer":"1914年","aliases":["1914年","1914","西暦1914","西暦1914年","AD1914","1914AD","CE1914","1914CE"],"ex":"1914年。サラエボ事件をきっかけに、列強の対立が大戦へ拡大した。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}],"region":"modern","level":"基礎"},{"id":200056,"topic":"year-56","title":"ロシア革命","year":1917,"era":"近代","q":"二月革命と十月革命が起きたロシア革命の年は？","answer":"1917年","aliases":["1917年","1917","西暦1917","西暦1917年","AD1917","1917AD","CE1917","1917CE"],"ex":"1917年。帝政崩壊とボリシェヴィキの権力掌握が同年に起きた。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}],"region":"modern","level":"基礎"},{"id":200057,"topic":"year-57","title":"第二次世界大戦の開始","year":1939,"era":"近代","q":"ドイツのポーランド侵攻を契機に欧州で第二次世界大戦が始まった年は？","answer":"1939年","aliases":["1939年","1939","西暦1939","西暦1939年","AD1939","1939AD","CE1939","1939CE"],"ex":"1939年。アジアでの戦争にはそれ以前からの連続性がある。ここでは欧州での開始年を問う。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}],"region":"modern","level":"基礎"},{"id":200058,"topic":"year-58","title":"国際連合の発足","year":1945,"era":"現代","q":"国際連合憲章が発効し、国際連合が正式に発足した年は？","answer":"1945年","aliases":["1945年","1945","西暦1945","西暦1945年","AD1945","1945AD","CE1945","1945CE"],"ex":"1945年。第一次世界大戦後の国際連盟と、第二次世界大戦後の国際連合を区別する。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}],"region":"contemporary","level":"基礎"},{"id":200059,"topic":"year-59","title":"ベルリンの壁の開放","year":1989,"era":"現代","q":"ベルリンの壁が開放された年は？","answer":"1989年","aliases":["1989年","1989","西暦1989","西暦1989年","AD1989","1989AD","CE1989","1989CE"],"ex":"1989年。東欧の変革を象徴する出来事。ドイツ統一は翌1990年である。","difficulty":"基礎","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}],"region":"contemporary","level":"基礎"},{"id":200060,"topic":"year-60","title":"陳勝・呉広の乱","year":-209,"era":"古代","region":"east","level":"標準","q":"「陳勝・呉広の乱」は何年？","answer":"前209年","aliases":["前209","紀元前209","紀元前209年","-209","BC209","209BC","BCE209","209BCE"],"ex":"前209年。秦末の反乱。厳しい支配への抵抗が各地に広がった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200061,"topic":"year-61","title":"呉楚七国の乱","year":-154,"era":"古代","region":"east","level":"標準","q":"「呉楚七国の乱」は何年？","answer":"前154年","aliases":["前154","紀元前154","紀元前154年","-154","BC154","154BC","BCE154","154BCE"],"ex":"前154年。前漢の中央集権化に対し諸侯王が反乱を起こした。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200062,"topic":"year-62","title":"張騫の最初の西域派遣（一般的な教科書表記）","year":-138,"era":"古代","region":"east","level":"発展","q":"「張騫の最初の西域派遣（一般的な教科書表記）」は何年？","answer":"前138年","aliases":["前138","紀元前138","紀元前138年","-138","BC138","138BC","BCE138","138BCE","前139","前139年","紀元前139年","-139","BC139","139BCE"],"ex":"前138年。武帝が大月氏との連携を求め、東西交通の拡大につながった。 前139年とする資料もある。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"},{"label":"張騫の派遣年代 · 中華書局","url":"https://www.chunghwabook.com.hk/blog/detail/id/636"}]},{"id":200063,"topic":"year-63","title":"漢の楽浪郡設置","year":-108,"era":"古代","region":"east","level":"標準","q":"「漢の楽浪郡設置」は何年？","answer":"前108年","aliases":["前108","紀元前108","紀元前108年","-108","BC108","108BC","BCE108","108BCE"],"ex":"前108年。武帝の朝鮮半島進出と結びつける。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200064,"topic":"year-64","title":"王莽による新の建国","year":9,"era":"古代","region":"east","level":"標準","q":"「王莽による新の建国」は何年？","answer":"9年","aliases":["9","西暦9年","西暦9","AD9","9AD","CE9","9CE"],"ex":"9年。前漢が終わり、復古的な改革が試みられた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200065,"topic":"year-65","title":"光武帝による後漢の成立","year":25,"era":"古代","region":"east","level":"標準","q":"「光武帝による後漢の成立」は何年？","answer":"25年","aliases":["25","西暦25年","西暦25","AD25","25AD","CE25","25CE"],"ex":"25年。劉秀が漢の皇帝となり、のち洛陽を都とした。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200066,"topic":"year-66","title":"大秦王安敦の使者の後漢来訪","year":166,"era":"古代","region":"east","level":"標準","q":"「大秦王安敦の使者の後漢来訪」は何年？","answer":"166年","aliases":["166","西暦166年","西暦166","AD166","166AD","CE166","166CE"],"ex":"166年。ローマ側の正式使節だったかは確定していない。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200067,"topic":"year-67","title":"赤壁の戦い","year":208,"era":"古代","region":"east","level":"標準","q":"「赤壁の戦い」は何年？","answer":"208年","aliases":["208","西暦208年","西暦208","AD208","208AD","CE208","208CE"],"ex":"208年。孫権・劉備側が曹操に対抗し、三国分立への流れが強まった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200068,"topic":"year-68","title":"劉備による蜀漢の建国","year":221,"era":"古代","region":"east","level":"標準","q":"「劉備による蜀漢の建国」は何年？","answer":"221年","aliases":["221","西暦221年","西暦221","AD221","221AD","CE221","221CE"],"ex":"221年。成都を中心に、漢の継承を掲げた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200069,"topic":"year-69","title":"孫権の皇帝即位","year":229,"era":"古代","region":"east","level":"発展","q":"「孫権の皇帝即位」は何年？","answer":"229年","aliases":["229","西暦229年","西暦229","AD229","229AD","CE229","229CE"],"ex":"229年。呉の皇帝即位と、魏・蜀の成立年を区別する。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200070,"topic":"year-70","title":"司馬炎による晋の建国","year":265,"era":"古代","region":"east","level":"標準","q":"「司馬炎による晋の建国」は何年？","answer":"265年","aliases":["265","西暦265年","西暦265","AD265","265AD","CE265","265CE"],"ex":"265年。魏から禅譲を受けた。中国統一は280年。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200071,"topic":"year-71","title":"西晋の滅亡","year":316,"era":"古代","region":"east","level":"標準","q":"「西晋の滅亡」は何年？","answer":"316年","aliases":["316","西暦316年","西暦316","AD316","316AD","CE316","316CE"],"ex":"316年。長安が陥落し、翌年に江南で東晋が成立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200072,"topic":"year-72","title":"拓跋珪による北魏の建国","year":386,"era":"古代","region":"east","level":"標準","q":"「拓跋珪による北魏の建国」は何年？","answer":"386年","aliases":["386","西暦386年","西暦386","AD386","386AD","CE386","386CE"],"ex":"386年。鮮卑の拓跋部が華北で勢力を伸ばした。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200073,"topic":"year-73","title":"北魏による華北統一","year":439,"era":"古代","region":"east","level":"標準","q":"「北魏による華北統一」は何年？","answer":"439年","aliases":["439","西暦439年","西暦439","AD439","439AD","CE439","439CE"],"ex":"439年。南朝との対立を南北朝の枠組みで整理する。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200074,"topic":"year-74","title":"北魏の均田令","year":485,"era":"古代","region":"east","level":"標準","q":"「北魏の均田令」は何年？","answer":"485年","aliases":["485","西暦485年","西暦485","AD485","485AD","CE485","485CE"],"ex":"485年。土地配分と租税・労役の確保を結びつける。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200075,"topic":"year-75","title":"六鎮の乱の開始","year":523,"era":"中世","region":"east","level":"標準","q":"「六鎮の乱の開始」は何年？","answer":"523年","aliases":["523","西暦523年","西暦523","AD523","523AD","CE523","523CE"],"ex":"523年。北魏の北辺軍鎮の反乱が政治的分裂につながった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200076,"topic":"year-76","title":"楊堅による隋の建国","year":581,"era":"中世","region":"east","level":"標準","q":"「楊堅による隋の建国」は何年？","answer":"581年","aliases":["581","西暦581年","西暦581","AD581","581AD","CE581","581CE"],"ex":"581年。中国再統一は589年であり、建国と区別する。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200077,"topic":"year-77","title":"隋の煬帝即位","year":604,"era":"中世","region":"east","level":"発展","q":"「隋の煬帝即位」は何年？","answer":"604年","aliases":["604","西暦604年","西暦604","AD604","604AD","CE604","604CE"],"ex":"604年。大運河建設や高句麗遠征と結びつける。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200078,"topic":"year-78","title":"玄武門の変","year":626,"era":"中世","region":"east","level":"標準","q":"「玄武門の変」は何年？","answer":"626年","aliases":["626","西暦626年","西暦626","AD626","626AD","CE626","626CE"],"ex":"626年。李世民が政敵を排し、唐の太宗となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200079,"topic":"year-79","title":"唐による東突厥の征服","year":630,"era":"中世","region":"east","level":"標準","q":"「唐による東突厥の征服」は何年？","answer":"630年","aliases":["630","西暦630年","西暦630","AD630","630AD","CE630","630CE"],"ex":"630年。太宗期の唐の対外拡大を示す。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200080,"topic":"year-80","title":"玄奘の帰国","year":645,"era":"中世","region":"east","level":"標準","q":"「玄奘の帰国」は何年？","answer":"645年","aliases":["645","西暦645年","西暦645","AD645","645AD","CE645","645CE"],"ex":"645年。インドなどで仏教を学び、長安で経典の翻訳に取り組んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200081,"topic":"year-81","title":"百済の滅亡","year":660,"era":"中世","region":"east","level":"標準","q":"「百済の滅亡」は何年？","answer":"660年","aliases":["660","西暦660年","西暦660","AD660","660AD","CE660","660CE"],"ex":"660年。唐・新羅連合軍が百済を倒した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200082,"topic":"year-82","title":"白村江の戦い","year":663,"era":"中世","region":"east","level":"標準","q":"「白村江の戦い」は何年？","answer":"663年","aliases":["663","西暦663年","西暦663","AD663","663AD","CE663","663CE"],"ex":"663年。倭・百済復興勢力が唐・新羅側と戦った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200083,"topic":"year-83","title":"高句麗の滅亡","year":668,"era":"中世","region":"east","level":"標準","q":"「高句麗の滅亡」は何年？","answer":"668年","aliases":["668","西暦668年","西暦668","AD668","668AD","CE668","668CE"],"ex":"668年。唐と新羅による攻撃で高句麗が滅びた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200084,"topic":"year-84","title":"新羅による唐軍の排除","year":676,"era":"中世","region":"east","level":"標準","q":"「新羅による唐軍の排除」は何年？","answer":"676年","aliases":["676","西暦676年","西暦676","AD676","676AD","CE676","676CE"],"ex":"676年。半島南部の統一支配を固めた時期として整理する。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200085,"topic":"year-85","title":"武則天の周の成立","year":690,"era":"中世","region":"east","level":"標準","q":"「武則天の周の成立」は何年？","answer":"690年","aliases":["690","西暦690年","西暦690","AD690","690AD","CE690","690CE"],"ex":"690年。唐の皇后だった武則天が皇帝となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200086,"topic":"year-86","title":"唐の玄宗即位","year":712,"era":"中世","region":"east","level":"発展","q":"「唐の玄宗即位」は何年？","answer":"712年","aliases":["712","西暦712年","西暦712","AD712","712AD","CE712","712CE"],"ex":"712年。開元の治と、後半の政治的混乱を区別する。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200087,"topic":"year-87","title":"唐の会昌の廃仏","year":845,"era":"中世","region":"east","level":"標準","q":"「唐の会昌の廃仏」は何年？","answer":"845年","aliases":["845","西暦845年","西暦845","AD845","845AD","CE845","845CE"],"ex":"845年。武宗による仏教弾圧。寺院経済と国家財政にも注目する。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200088,"topic":"year-88","title":"黄巣の乱の開始","year":875,"era":"中世","region":"east","level":"標準","q":"「黄巣の乱の開始」は何年？","answer":"875年","aliases":["875","西暦875年","西暦875","AD875","875AD","CE875","875CE"],"ex":"875年。唐末の大規模反乱で、節度使の自立が進んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200089,"topic":"year-89","title":"唐の滅亡","year":907,"era":"中世","region":"east","level":"標準","q":"「唐の滅亡」は何年？","answer":"907年","aliases":["907","西暦907年","西暦907","AD907","907AD","CE907","907CE"],"ex":"907年。朱全忠が後梁を建て、五代十国の分裂期に入った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200090,"topic":"year-90","title":"耶律阿保機による契丹の建国","year":916,"era":"中世","region":"east","level":"標準","q":"「耶律阿保機による契丹の建国」は何年？","answer":"916年","aliases":["916","西暦916年","西暦916","AD916","916AD","CE916","916CE"],"ex":"916年。遼の前身。北方勢力と宋との関係を整理する。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200091,"topic":"year-91","title":"高麗による後三国統一","year":936,"era":"中世","region":"east","level":"標準","q":"「高麗による後三国統一」は何年？","answer":"936年","aliases":["936","西暦936年","西暦936","AD936","936AD","CE936","936CE"],"ex":"936年。王建の建国918年とは別の段階である。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200092,"topic":"year-92","title":"宋と遼の澶淵の盟の成立年（日本の教科書で一般的な表記）","year":1004,"era":"中世","region":"east","level":"発展","q":"「宋と遼の澶淵の盟の成立年（日本の教科書で一般的な表記）」は何年？","answer":"1004年","aliases":["1004","西暦1004年","西暦1004","AD1004","1004AD","CE1004","1004CE","1005","1005年"],"ex":"1004年。旧暦景徳元年の協定。西暦換算で1005年とする資料もある。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200093,"topic":"year-93","title":"金による遼の滅亡","year":1125,"era":"中世","region":"east","level":"標準","q":"「金による遼の滅亡」は何年？","answer":"1125年","aliases":["1125","西暦1125年","西暦1125","AD1125","1125AD","CE1125","1125CE"],"ex":"1125年。女真の金が契丹の遼を倒し、次に宋へ圧力をかけた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200094,"topic":"year-94","title":"宋金の紹興の和議","year":1141,"era":"中世","region":"east","level":"標準","q":"「宋金の紹興の和議」は何年？","answer":"1141年","aliases":["1141","西暦1141年","西暦1141","AD1141","1141AD","CE1141","1141CE"],"ex":"1141年。南宋が金に歳貢を支払う関係を定めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200095,"topic":"year-95","title":"モンゴル軍による金の中都攻略","year":1215,"era":"中世","region":"east","level":"標準","q":"「モンゴル軍による金の中都攻略」は何年？","answer":"1215年","aliases":["1215","西暦1215年","西暦1215","AD1215","1215AD","CE1215","1215CE"],"ex":"1215年。現在の北京にあたる金の都を攻め落とした。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200096,"topic":"year-96","title":"西夏の滅亡","year":1227,"era":"中世","region":"east","level":"標準","q":"「西夏の滅亡」は何年？","answer":"1227年","aliases":["1227","西暦1227年","西暦1227","AD1227","1227AD","CE1227","1227CE"],"ex":"1227年。モンゴルの西夏遠征とチンギス＝ハンの死を結びつける。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200097,"topic":"year-97","title":"金の滅亡","year":1234,"era":"中世","region":"east","level":"標準","q":"「金の滅亡」は何年？","answer":"1234年","aliases":["1234","西暦1234年","西暦1234","AD1234","1234AD","CE1234","1234CE"],"ex":"1234年。モンゴルと南宋が金を倒し、その後両者が対立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200098,"topic":"year-98","title":"モンゴル軍によるバグダード攻略","year":1258,"era":"中世","region":"east","level":"標準","q":"「モンゴル軍によるバグダード攻略」は何年？","answer":"1258年","aliases":["1258","西暦1258年","西暦1258","AD1258","1258AD","CE1258","1258CE"],"ex":"1258年。アッバース朝のバグダードのカリフ政権が終わった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200099,"topic":"year-99","title":"フビライのハン即位","year":1260,"era":"中世","region":"east","level":"発展","q":"「フビライのハン即位」は何年？","answer":"1260年","aliases":["1260","西暦1260年","西暦1260","AD1260","1260AD","CE1260","1260CE"],"ex":"1260年。ハン位継承争いとモンゴル帝国の分立を結びつける。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200100,"topic":"year-100","title":"元の第1次日本遠征","year":1274,"era":"中世","region":"east","level":"標準","q":"「元の第1次日本遠征」は何年？","answer":"1274年","aliases":["1274","西暦1274年","西暦1274","AD1274","1274AD","CE1274","1274CE"],"ex":"1274年。日本では文永の役と呼ばれる。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200101,"topic":"year-101","title":"元の第2次日本遠征","year":1281,"era":"中世","region":"east","level":"標準","q":"「元の第2次日本遠征」は何年？","answer":"1281年","aliases":["1281","西暦1281年","西暦1281","AD1281","1281AD","CE1281","1281CE"],"ex":"1281年。日本では弘安の役と呼ばれる。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200102,"topic":"year-102","title":"フビライの死","year":1294,"era":"中世","region":"east","level":"標準","q":"「フビライの死」は何年？","answer":"1294年","aliases":["1294","西暦1294年","西暦1294","AD1294","1294AD","CE1294","1294CE"],"ex":"1294年。元初期の対外拡大の時期を整理する基準となる。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200103,"topic":"year-103","title":"紅巾の乱の開始","year":1351,"era":"中世","region":"east","level":"標準","q":"「紅巾の乱の開始」は何年？","answer":"1351年","aliases":["1351","西暦1351年","西暦1351","AD1351","1351AD","CE1351","1351CE"],"ex":"1351年。元末の反乱から朱元璋が台頭した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200104,"topic":"year-104","title":"靖難の役の終結と永楽帝即位","year":1402,"era":"中世","region":"east","level":"発展","q":"「靖難の役の終結と永楽帝即位」は何年？","answer":"1402年","aliases":["1402","西暦1402年","西暦1402","AD1402","1402AD","CE1402","1402CE"],"ex":"1402年。建文帝の政権を倒し、明の政治を再編した。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200105,"topic":"year-105","title":"鄭和の最後の遠征の帰還","year":1433,"era":"中世","region":"east","level":"標準","q":"「鄭和の最後の遠征の帰還」は何年？","answer":"1433年","aliases":["1433","西暦1433年","西暦1433","AD1433","1433AD","CE1433","1433CE"],"ex":"1433年。最初の遠征1405年と、計7回の遠征を結びつける。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200106,"topic":"year-106","title":"明とアルタン＝ハンの和議","year":1571,"era":"近世","region":"east","level":"標準","q":"「明とアルタン＝ハンの和議」は何年？","answer":"1571年","aliases":["1571","西暦1571年","西暦1571","AD1571","1571AD","CE1571","1571CE"],"ex":"1571年。北方のモンゴル勢力と明が交易関係を整えた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200107,"topic":"year-107","title":"豊臣秀吉による第1次朝鮮侵略","year":1592,"era":"近世","region":"east","level":"標準","q":"「豊臣秀吉による第1次朝鮮侵略」は何年？","answer":"1592年","aliases":["1592","西暦1592年","西暦1592","AD1592","1592AD","CE1592","1592CE"],"ex":"1592年。日本では文禄の役。明も朝鮮側で参戦した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200108,"topic":"year-108","title":"豊臣秀吉による第2次朝鮮侵略","year":1597,"era":"近世","region":"east","level":"標準","q":"「豊臣秀吉による第2次朝鮮侵略」は何年？","answer":"1597年","aliases":["1597","西暦1597年","西暦1597","AD1597","1597AD","CE1597","1597CE"],"ex":"1597年。日本では慶長の役。1598年に日本軍が撤退した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200109,"topic":"year-109","title":"後金の第1次朝鮮侵入","year":1627,"era":"近世","region":"east","level":"標準","q":"「後金の第1次朝鮮侵入」は何年？","answer":"1627年","aliases":["1627","西暦1627年","西暦1627","AD1627","1627AD","CE1627","1627CE"],"ex":"1627年。丁卯胡乱。1636年の清による再侵入と区別する。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200110,"topic":"year-110","title":"朝鮮の清への服属","year":1637,"era":"近世","region":"east","level":"標準","q":"「朝鮮の清への服属」は何年？","answer":"1637年","aliases":["1637","西暦1637年","西暦1637","AD1637","1637AD","CE1637","1637CE"],"ex":"1637年。前年に始まった丙子胡乱の結果、清との君臣関係を受け入れた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200111,"topic":"year-111","title":"清による鄭氏台湾の制圧","year":1683,"era":"近世","region":"east","level":"標準","q":"「清による鄭氏台湾の制圧」は何年？","answer":"1683年","aliases":["1683","西暦1683年","西暦1683","AD1683","1683AD","CE1683","1683CE"],"ex":"1683年。鄭氏政権の終わりと海上政策の変化を整理する。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200112,"topic":"year-112","title":"清の軍機房設置（軍機処の起源）","year":1729,"era":"近世","region":"east","level":"発展","q":"「清の軍機房設置（軍機処の起源）」は何年？","answer":"1729年","aliases":["1729","西暦1729年","西暦1729","AD1729","1729AD","CE1729","1729CE"],"ex":"1729年。雍正帝の西北軍事への対応から皇帝直属の機関が発達した。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200113,"topic":"year-113","title":"清の広州一港への欧州船貿易制限","year":1757,"era":"近世","region":"east","level":"標準","q":"「清の広州一港への欧州船貿易制限」は何年？","answer":"1757年","aliases":["1757","西暦1757年","西暦1757","AD1757","1757AD","CE1757","1757CE"],"ex":"1757年。いわゆる広東貿易体制。中国のすべての対外貿易が広州だけになったわけではない。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200114,"topic":"year-114","title":"マカートニーの清来訪","year":1793,"era":"近世","region":"east","level":"標準","q":"「マカートニーの清来訪」は何年？","answer":"1793年","aliases":["1793","西暦1793年","西暦1793","AD1793","1793AD","CE1793","1793CE"],"ex":"1793年。乾隆帝期にイギリスが通商関係の変更を求めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200115,"topic":"year-115","title":"白蓮教徒の乱の開始","year":1796,"era":"近世","region":"east","level":"標準","q":"「白蓮教徒の乱の開始」は何年？","answer":"1796年","aliases":["1796","西暦1796年","西暦1796","AD1796","1796AD","CE1796","1796CE"],"ex":"1796年。清の支配と社会の変化を示す内乱として整理する。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200116,"topic":"year-116","title":"林則徐による広州でのアヘン没収","year":1839,"era":"近代","region":"east","level":"標準","q":"「林則徐による広州でのアヘン没収」は何年？","answer":"1839年","aliases":["1839","西暦1839年","西暦1839","AD1839","1839AD","CE1839","1839CE"],"ex":"1839年。アヘン戦争に至る対立の激化と結びつける。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200117,"topic":"year-117","title":"アヘン戦争の開始","year":1840,"era":"近代","region":"east","level":"標準","q":"「アヘン戦争の開始」は何年？","answer":"1840年","aliases":["1840","西暦1840年","西暦1840","AD1840","1840AD","CE1840","1840CE"],"ex":"1840年。清とイギリスが戦い、南京条約に至った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200118,"topic":"year-118","title":"太平天国の金田蜂起","year":1851,"era":"近代","region":"east","level":"発展","q":"「太平天国の金田蜂起」は何年？","answer":"1851年","aliases":["1851","西暦1851年","西暦1851","AD1851","1851AD","CE1851","1851CE"],"ex":"1851年。洪秀全が指導した大規模な反乱が始まった。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200119,"topic":"year-119","title":"アロー戦争の開始","year":1856,"era":"近代","region":"east","level":"標準","q":"「アロー戦争の開始」は何年？","answer":"1856年","aliases":["1856","西暦1856年","西暦1856","AD1856","1856AD","CE1856","1856CE"],"ex":"1856年。イギリス・フランスの清への軍事介入が拡大した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200120,"topic":"year-120","title":"天津条約の締結","year":1858,"era":"近代","region":"east","level":"標準","q":"「天津条約の締結」は何年？","answer":"1858年","aliases":["1858","西暦1858年","西暦1858","AD1858","1858AD","CE1858","1858CE"],"ex":"1858年。清と英仏などの条約。批准をめぐり戦争が続いた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200121,"topic":"year-121","title":"北京条約の締結","year":1860,"era":"近代","region":"east","level":"標準","q":"「北京条約の締結」は何年？","answer":"1860年","aliases":["1860","西暦1860年","西暦1860","AD1860","1860AD","CE1860","1860CE"],"ex":"1860年。天津条約の内容を確認し、追加の開港などを認めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200122,"topic":"year-122","title":"太平天国の天京陥落","year":1864,"era":"近代","region":"east","level":"標準","q":"「太平天国の天京陥落」は何年？","answer":"1864年","aliases":["1864","西暦1864年","西暦1864","AD1864","1864AD","CE1864","1864CE"],"ex":"1864年。曾国藩らの勢力による鎮圧が進み、太平天国は崩壊した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200123,"topic":"year-123","title":"日朝修好条規の締結","year":1876,"era":"近代","region":"east","level":"標準","q":"「日朝修好条規の締結」は何年？","answer":"1876年","aliases":["1876","西暦1876年","西暦1876","AD1876","1876AD","CE1876","1876CE"],"ex":"1876年。朝鮮が日本と結んだ不平等条約で、開国の画期となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200124,"topic":"year-124","title":"清仏戦争の開始","year":1884,"era":"近代","region":"east","level":"標準","q":"「清仏戦争の開始」は何年？","answer":"1884年","aliases":["1884","西暦1884年","西暦1884","AD1884","1884AD","CE1884","1884CE"],"ex":"1884年。ベトナム支配をめぐり清とフランスが戦った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200125,"topic":"year-125","title":"天津条約による清仏戦争の終結","year":1885,"era":"近代","region":"east","level":"標準","q":"「天津条約による清仏戦争の終結」は何年？","answer":"1885年","aliases":["1885","西暦1885年","西暦1885","AD1885","1885AD","CE1885","1885CE"],"ex":"1885年。清がフランスのベトナム保護権を認めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200126,"topic":"year-126","title":"日清戦争の開始","year":1894,"era":"近代","region":"east","level":"標準","q":"「日清戦争の開始」は何年？","answer":"1894年","aliases":["1894","西暦1894年","西暦1894","AD1894","1894AD","CE1894","1894CE"],"ex":"1894年。朝鮮半島をめぐる対立が戦争に発展した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200127,"topic":"year-127","title":"大韓帝国の成立","year":1897,"era":"近代","region":"east","level":"標準","q":"「大韓帝国の成立」は何年？","answer":"1897年","aliases":["1897","西暦1897年","西暦1897","AD1897","1897AD","CE1897","1897CE"],"ex":"1897年。高宗が皇帝を称し、対外的な独立を示そうとした。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200128,"topic":"year-128","title":"義和団事件と列強の北京出兵","year":1900,"era":"近代","region":"east","level":"標準","q":"「義和団事件と列強の北京出兵」は何年？","answer":"1900年","aliases":["1900","西暦1900年","西暦1900","AD1900","1900AD","CE1900","1900CE"],"ex":"1900年。排外運動に対し、列強が共同で軍事介入した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200129,"topic":"year-129","title":"北京議定書の調印","year":1901,"era":"近代","region":"east","level":"標準","q":"「北京議定書の調印」は何年？","answer":"1901年","aliases":["1901","西暦1901年","西暦1901","AD1901","1901AD","CE1901","1901CE"],"ex":"1901年。清に賠償金などが課され、列強の影響力が強まった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200130,"topic":"year-130","title":"中国同盟会の結成","year":1905,"era":"近代","region":"east","level":"標準","q":"「中国同盟会の結成」は何年？","answer":"1905年","aliases":["1905","西暦1905年","西暦1905","AD1905","1905AD","CE1905","1905CE"],"ex":"1905年。孫文らが東京で革命運動の組織を統合した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200131,"topic":"year-131","title":"日本による韓国併合","year":1910,"era":"近代","region":"east","level":"標準","q":"「日本による韓国併合」は何年？","answer":"1910年","aliases":["1910","西暦1910年","西暦1910","AD1910","1910AD","CE1910","1910CE"],"ex":"1910年。韓国統監府の設置1906年と区別する。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200132,"topic":"year-132","title":"中華民国の成立","year":1912,"era":"近代","region":"east","level":"標準","q":"「中華民国の成立」は何年？","answer":"1912年","aliases":["1912","西暦1912年","西暦1912","AD1912","1912AD","CE1912","1912CE"],"ex":"1912年。辛亥革命翌年に孫文が臨時大総統となり、清帝が退位した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200133,"topic":"year-133","title":"日本の対華二十一か条要求","year":1915,"era":"現代","region":"east","level":"標準","q":"「日本の対華二十一か条要求」は何年？","answer":"1915年","aliases":["1915","西暦1915年","西暦1915","AD1915","1915AD","CE1915","1915CE"],"ex":"1915年。第一次世界大戦中、日本が袁世凱政権に要求を提示した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200134,"topic":"year-134","title":"中国共産党の成立","year":1921,"era":"現代","region":"east","level":"標準","q":"「中国共産党の成立」は何年？","answer":"1921年","aliases":["1921","西暦1921年","西暦1921","AD1921","1921AD","CE1921","1921CE"],"ex":"1921年。上海などで結成大会が行われた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200135,"topic":"year-135","title":"第1次国共合作の成立","year":1924,"era":"現代","region":"east","level":"標準","q":"「第1次国共合作の成立」は何年？","answer":"1924年","aliases":["1924","西暦1924年","西暦1924","AD1924","1924AD","CE1924","1924CE"],"ex":"1924年。国民党と共産党が協力し、反帝国主義と統一をめざした。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200136,"topic":"year-136","title":"中国国民革命軍の北伐開始","year":1926,"era":"現代","region":"east","level":"標準","q":"「中国国民革命軍の北伐開始」は何年？","answer":"1926年","aliases":["1926","西暦1926年","西暦1926","AD1926","1926AD","CE1926","1926CE"],"ex":"1926年。広東から北方の軍閥勢力へ進軍した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200137,"topic":"year-137","title":"上海クーデタ","year":1927,"era":"現代","region":"east","level":"標準","q":"「上海クーデタ」は何年？","answer":"1927年","aliases":["1927","西暦1927年","西暦1927","AD1927","1927AD","CE1927","1927CE"],"ex":"1927年。蔣介石が共産党勢力を弾圧し、国共分裂が進んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200138,"topic":"year-138","title":"張学良の易幟","year":1928,"era":"現代","region":"east","level":"発展","q":"「張学良の易幟」は何年？","answer":"1928年","aliases":["1928","西暦1928年","西暦1928","AD1928","1928AD","CE1928","1928CE"],"ex":"1928年。南京の国民政府への服属を表明し、中国の形式的統一が進んだ。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200139,"topic":"year-139","title":"満州事変","year":1931,"era":"現代","region":"east","level":"標準","q":"「満州事変」は何年？","answer":"1931年","aliases":["1931","西暦1931年","西暦1931","AD1931","1931AD","CE1931","1931CE"],"ex":"1931年。柳条湖事件をきっかけに日本軍が満州で軍事行動を拡大した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200140,"topic":"year-140","title":"満州国の成立","year":1932,"era":"現代","region":"east","level":"標準","q":"「満州国の成立」は何年？","answer":"1932年","aliases":["1932","西暦1932年","西暦1932","AD1932","1932AD","CE1932","1932CE"],"ex":"1932年。日本の強い影響下にある国家がつくられ、国際問題となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200141,"topic":"year-141","title":"中国共産党の長征開始","year":1934,"era":"現代","region":"east","level":"標準","q":"「中国共産党の長征開始」は何年？","answer":"1934年","aliases":["1934","西暦1934年","西暦1934","AD1934","1934AD","CE1934","1934CE"],"ex":"1934年。国民党の包囲を逃れて根拠地を移動した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200142,"topic":"year-142","title":"西安事件","year":1936,"era":"現代","region":"east","level":"標準","q":"「西安事件」は何年？","answer":"1936年","aliases":["1936","西暦1936年","西暦1936","AD1936","1936AD","CE1936","1936CE"],"ex":"1936年。蔣介石が拘束され、抗日協力への転換が促された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200143,"topic":"year-143","title":"日本の降伏と朝鮮の植民地支配の終結","year":1945,"era":"現代","region":"east","level":"標準","q":"「日本の降伏と朝鮮の植民地支配の終結」は何年？","answer":"1945年","aliases":["1945","西暦1945年","西暦1945","AD1945","1945AD","CE1945","1945CE"],"ex":"1945年。第二次世界大戦の終戦が東アジアの政治秩序を変えた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200144,"topic":"year-144","title":"大韓民国と朝鮮民主主義人民共和国の成立","year":1948,"era":"現代","region":"east","level":"標準","q":"「大韓民国と朝鮮民主主義人民共和国の成立」は何年？","answer":"1948年","aliases":["1948","西暦1948年","西暦1948","AD1948","1948AD","CE1948","1948CE"],"ex":"1948年。朝鮮半島の南北に別々の政府が成立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200145,"topic":"year-145","title":"中華人民共和国憲法の制定","year":1954,"era":"現代","region":"east","level":"標準","q":"「中華人民共和国憲法の制定」は何年？","answer":"1954年","aliases":["1954","西暦1954年","西暦1954","AD1954","1954AD","CE1954","1954CE"],"ex":"1954年。全国人民代表大会が開かれ、新たな国家制度が整えられた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200146,"topic":"year-146","title":"中国の大躍進開始","year":1958,"era":"現代","region":"east","level":"標準","q":"「中国の大躍進開始」は何年？","answer":"1958年","aliases":["1958","西暦1958年","西暦1958","AD1958","1958AD","CE1958","1958CE"],"ex":"1958年。急激な工業化・農業集団化が社会と経済を混乱させた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200147,"topic":"year-147","title":"文化大革命の開始","year":1966,"era":"現代","region":"east","level":"標準","q":"「文化大革命の開始」は何年？","answer":"1966年","aliases":["1966","西暦1966年","西暦1966","AD1966","1966AD","CE1966","1966CE"],"ex":"1966年。毛沢東が発動し、政治・社会・文化に広範な混乱をもたらした。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200148,"topic":"year-148","title":"国連における中国代表権の交代","year":1971,"era":"現代","region":"east","level":"標準","q":"「国連における中国代表権の交代」は何年？","answer":"1971年","aliases":["1971","西暦1971年","西暦1971","AD1971","1971AD","CE1971","1971CE"],"ex":"1971年。中華人民共和国の代表が中国の議席を占めることになった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200149,"topic":"year-149","title":"ニクソン訪中","year":1972,"era":"現代","region":"east","level":"標準","q":"「ニクソン訪中」は何年？","answer":"1972年","aliases":["1972","西暦1972年","西暦1972","AD1972","1972AD","CE1972","1972CE"],"ex":"1972年。米中関係改善の画期。国交樹立は1979年。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200150,"topic":"year-150","title":"日中共同声明","year":1972,"era":"現代","region":"east","level":"標準","q":"「日中共同声明」は何年？","answer":"1972年","aliases":["1972","西暦1972年","西暦1972","AD1972","1972AD","CE1972","1972CE"],"ex":"1972年。日本と中華人民共和国の国交が正常化した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200151,"topic":"year-151","title":"中国の改革開放路線への転換","year":1978,"era":"現代","region":"east","level":"標準","q":"「中国の改革開放路線への転換」は何年？","answer":"1978年","aliases":["1978","西暦1978年","西暦1978","AD1978","1978AD","CE1978","1978CE"],"ex":"1978年。鄧小平のもとで経済改革と対外開放が進んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200152,"topic":"year-152","title":"米中国交樹立","year":1979,"era":"現代","region":"east","level":"標準","q":"「米中国交樹立」は何年？","answer":"1979年","aliases":["1979","西暦1979年","西暦1979","AD1979","1979AD","CE1979","1979CE"],"ex":"1979年。ニクソン訪中から7年後に外交関係が正式に成立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200153,"topic":"year-153","title":"中国の天安門事件","year":1989,"era":"現代","region":"east","level":"標準","q":"「中国の天安門事件」は何年？","answer":"1989年","aliases":["1989","西暦1989年","西暦1989","AD1989","1989AD","CE1989","1989CE"],"ex":"1989年。民主化を求める運動を軍が武力で鎮圧した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200154,"topic":"year-154","title":"香港の中国返還","year":1997,"era":"現代","region":"east","level":"標準","q":"「香港の中国返還」は何年？","answer":"1997年","aliases":["1997","西暦1997年","西暦1997","AD1997","1997AD","CE1997","1997CE"],"ex":"1997年。イギリスから返還され、特別行政区となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200155,"topic":"year-155","title":"マカオの中国返還","year":1999,"era":"現代","region":"east","level":"標準","q":"「マカオの中国返還」は何年？","answer":"1999年","aliases":["1999","西暦1999年","西暦1999","AD1999","1999AD","CE1999","1999CE"],"ex":"1999年。ポルトガルから返還され、特別行政区となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200156,"topic":"year-156","title":"中国のWTO加盟","year":2001,"era":"現代","region":"east","level":"標準","q":"「中国のWTO加盟」は何年？","answer":"2001年","aliases":["2001","西暦2001年","西暦2001","AD2001","2001AD","CE2001","2001CE"],"ex":"2001年。世界経済への統合がさらに進んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"},{"label":"王朝・時代の概観 · Columbia University","url":"https://afe.easia.columbia.edu/timelines/china_timeline.htm"}]},{"id":200157,"topic":"year-157","title":"アレクサンドロスのインド侵入","year":-326,"era":"古代","region":"south","level":"標準","q":"「アレクサンドロスのインド侵入」は何年？","answer":"前326年","aliases":["前326","紀元前326","紀元前326年","-326","BC326","326BC","BCE326","326BCE"],"ex":"前326年。マケドニア軍がインダス流域へ進出した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200158,"topic":"year-158","title":"アショーカ王のカリンガ征服の伝統的な年代","year":-261,"era":"古代","region":"south","level":"発展","q":"「アショーカ王のカリンガ征服の伝統的な年代」は何年？","answer":"前261年","aliases":["前261","紀元前261","紀元前261年","-261","BC261","261BC","BCE261","261BCE"],"ex":"前261年。激しい戦争の経験と仏教保護の関係が語られる。年代には推定が含まれる。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"},{"label":"カリンガ征服の年代 · PBS","url":"https://www.pbs.org/thestoryofindia/timeline/2/"}]},{"id":200159,"topic":"year-159","title":"グプタ朝の紀元の開始","year":320,"era":"古代","region":"south","level":"標準","q":"「グプタ朝の紀元の開始」は何年？","answer":"320年","aliases":["320","西暦320年","西暦320","AD320","320AD","CE320","320CE"],"ex":"320年。チャンドラグプタ1世期の成立を考える基準となる。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200160,"topic":"year-160","title":"ハルシャ王の即位","year":606,"era":"中世","region":"south","level":"発展","q":"「ハルシャ王の即位」は何年？","answer":"606年","aliases":["606","西暦606年","西暦606","AD606","606AD","CE606","606CE"],"ex":"606年。北インドに勢力を広げ、玄奘の訪問を受けた。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200161,"topic":"year-161","title":"アラブ軍のシンド侵入","year":711,"era":"中世","region":"south","level":"標準","q":"「アラブ軍のシンド侵入」は何年？","answer":"711年","aliases":["711","西暦711年","西暦711","AD711","711AD","CE711","711CE"],"ex":"711年。インダス川下流域にイスラーム勢力が進出した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200162,"topic":"year-162","title":"インドの奴隷王朝成立","year":1206,"era":"中世","region":"south","level":"標準","q":"「インドの奴隷王朝成立」は何年？","answer":"1206年","aliases":["1206","西暦1206年","西暦1206","AD1206","1206AD","CE1206","1206CE"],"ex":"1206年。アイバクが建てたデリー＝スルタン朝最初の王朝。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200163,"topic":"year-163","title":"ハルジー朝の成立","year":1290,"era":"中世","region":"south","level":"標準","q":"「ハルジー朝の成立」は何年？","answer":"1290年","aliases":["1290","西暦1290年","西暦1290","AD1290","1290AD","CE1290","1290CE"],"ex":"1290年。デリー＝スルタン朝の第2の王朝。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200164,"topic":"year-164","title":"トゥグルク朝の成立","year":1320,"era":"中世","region":"south","level":"標準","q":"「トゥグルク朝の成立」は何年？","answer":"1320年","aliases":["1320","西暦1320年","西暦1320","AD1320","1320AD","CE1320","1320CE"],"ex":"1320年。デリーを中心に南インドへの支配拡大が図られた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200165,"topic":"year-165","title":"ヴィジャヤナガル王国の成立","year":1336,"era":"中世","region":"south","level":"標準","q":"「ヴィジャヤナガル王国の成立」は何年？","answer":"1336年","aliases":["1336","西暦1336年","西暦1336","AD1336","1336AD","CE1336","1336CE"],"ex":"1336年。南インドのヒンドゥー勢力が形成した王国。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200166,"topic":"year-166","title":"ティムールのデリー侵入","year":1398,"era":"中世","region":"south","level":"標準","q":"「ティムールのデリー侵入」は何年？","answer":"1398年","aliases":["1398","西暦1398年","西暦1398","AD1398","1398AD","CE1398","1398CE"],"ex":"1398年。北インドに大きな被害を与え、スルタン朝を弱体化させた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200167,"topic":"year-167","title":"ヴァスコ＝ダ＝ガマのカリカット到達","year":1498,"era":"中世","region":"south","level":"標準","q":"「ヴァスコ＝ダ＝ガマのカリカット到達」は何年？","answer":"1498年","aliases":["1498","西暦1498年","西暦1498","AD1498","1498AD","CE1498","1498CE"],"ex":"1498年。アフリカ南端を回り、ヨーロッパとインドを海路で結んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200168,"topic":"year-168","title":"第1次パーニーパットの戦い","year":1526,"era":"近世","region":"south","level":"標準","q":"「第1次パーニーパットの戦い」は何年？","answer":"1526年","aliases":["1526","西暦1526年","西暦1526","AD1526","1526AD","CE1526","1526CE"],"ex":"1526年。バーブルがロディー朝を倒し、ムガル帝国成立の画期となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200169,"topic":"year-169","title":"アクバルの即位","year":1556,"era":"近世","region":"south","level":"発展","q":"「アクバルの即位」は何年？","answer":"1556年","aliases":["1556","西暦1556年","西暦1556","AD1556","1556AD","CE1556","1556CE"],"ex":"1556年。ムガル帝国の支配拡大と宗教的融和策を結びつける。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200170,"topic":"year-170","title":"アウラングゼーブの即位","year":1658,"era":"近世","region":"south","level":"発展","q":"「アウラングゼーブの即位」は何年？","answer":"1658年","aliases":["1658","西暦1658年","西暦1658","AD1658","1658AD","CE1658","1658CE"],"ex":"1658年。ムガル帝国最大版図と宗教政策の変化を結びつける。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200171,"topic":"year-171","title":"プラッシーの戦い","year":1757,"era":"近世","region":"south","level":"標準","q":"「プラッシーの戦い」は何年？","answer":"1757年","aliases":["1757","西暦1757年","西暦1757","AD1757","1757AD","CE1757","1757CE"],"ex":"1757年。イギリス東インド会社がベンガルで優位を確立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200172,"topic":"year-172","title":"ブクサールの戦い","year":1764,"era":"近世","region":"south","level":"標準","q":"「ブクサールの戦い」は何年？","answer":"1764年","aliases":["1764","西暦1764年","西暦1764","AD1764","1764AD","CE1764","1764CE"],"ex":"1764年。イギリス東インド会社がインド諸勢力を破った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200173,"topic":"year-173","title":"東インド会社によるベンガルなどの徴税権獲得","year":1765,"era":"近世","region":"south","level":"標準","q":"「東インド会社によるベンガルなどの徴税権獲得」は何年？","answer":"1765年","aliases":["1765","西暦1765年","西暦1765","AD1765","1765AD","CE1765","1765CE"],"ex":"1765年。軍事的勝利が財政・行政支配の拡大につながった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200174,"topic":"year-174","title":"インド大反乱の開始","year":1857,"era":"近代","region":"south","level":"標準","q":"「インド大反乱の開始」は何年？","answer":"1857年","aliases":["1857","西暦1857年","西暦1857","AD1857","1857AD","CE1857","1857CE"],"ex":"1857年。シパーヒーの反乱から広がり、会社支配の転換点となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200175,"topic":"year-175","title":"インド統治のイギリス国王への移管","year":1858,"era":"近代","region":"south","level":"標準","q":"「インド統治のイギリス国王への移管」は何年？","answer":"1858年","aliases":["1858","西暦1858年","西暦1858","AD1858","1858AD","CE1858","1858CE"],"ex":"1858年。東インド会社の支配が終わり、直轄統治となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200176,"topic":"year-176","title":"ヴィクトリア女王のインド皇帝即位宣言","year":1877,"era":"近代","region":"south","level":"発展","q":"「ヴィクトリア女王のインド皇帝即位宣言」は何年？","answer":"1877年","aliases":["1877","西暦1877年","西暦1877","AD1877","1877AD","CE1877","1877CE"],"ex":"1877年。イギリスのインド帝国支配を象徴した。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200177,"topic":"year-177","title":"インド国民会議の成立","year":1885,"era":"近代","region":"south","level":"標準","q":"「インド国民会議の成立」は何年？","answer":"1885年","aliases":["1885","西暦1885年","西暦1885","AD1885","1885AD","CE1885","1885CE"],"ex":"1885年。当初は穏健な政治要求を掲げ、のち独立運動の中心となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200178,"topic":"year-178","title":"ベンガル分割令","year":1905,"era":"近代","region":"south","level":"標準","q":"「ベンガル分割令」は何年？","answer":"1905年","aliases":["1905","西暦1905年","西暦1905","AD1905","1905AD","CE1905","1905CE"],"ex":"1905年。イギリスの政策に対し、スワデーシー運動などが広がった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200179,"topic":"year-179","title":"全インド＝ムスリム連盟の成立","year":1906,"era":"近代","region":"south","level":"標準","q":"「全インド＝ムスリム連盟の成立」は何年？","answer":"1906年","aliases":["1906","西暦1906年","西暦1906","AD1906","1906AD","CE1906","1906CE"],"ex":"1906年。ムスリムの政治組織として発足し、のちパキスタン運動を担った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200180,"topic":"year-180","title":"アムリットサル虐殺事件","year":1919,"era":"現代","region":"south","level":"標準","q":"「アムリットサル虐殺事件」は何年？","answer":"1919年","aliases":["1919","西暦1919年","西暦1919","AD1919","1919AD","CE1919","1919CE"],"ex":"1919年。イギリス軍が集会参加者に発砲し、独立運動が高揚した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200181,"topic":"year-181","title":"ガンディーの塩の行進","year":1930,"era":"現代","region":"south","level":"標準","q":"「ガンディーの塩の行進」は何年？","answer":"1930年","aliases":["1930","西暦1930年","西暦1930","AD1930","1930AD","CE1930","1930CE"],"ex":"1930年。塩の専売への抵抗を通じ、不服従運動を展開した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200182,"topic":"year-182","title":"インドとパキスタンの独立","year":1947,"era":"現代","region":"south","level":"標準","q":"「インドとパキスタンの独立」は何年？","answer":"1947年","aliases":["1947","西暦1947年","西暦1947","AD1947","1947AD","CE1947","1947CE"],"ex":"1947年。イギリス領インドが分離独立し、大規模な人口移動が起きた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200183,"topic":"year-183","title":"バングラデシュの独立","year":1971,"era":"現代","region":"south","level":"標準","q":"「バングラデシュの独立」は何年？","answer":"1971年","aliases":["1971","西暦1971年","西暦1971","AD1971","1971AD","CE1971","1971CE"],"ex":"1971年。東パキスタンが独立し、南アジアの国家構成が変わった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200184,"topic":"year-184","title":"クメール王朝のアンコール時代開始の伝統的年代","year":802,"era":"中世","region":"sea","level":"発展","q":"「クメール王朝のアンコール時代開始の伝統的年代」は何年？","answer":"802年","aliases":["802","西暦802年","西暦802","AD802","802AD","CE802","802CE"],"ex":"802年。ジャヤヴァルマン2世の王権確立と結びつけられる。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200185,"topic":"year-185","title":"ベトナムの呉朝成立","year":939,"era":"中世","region":"sea","level":"標準","q":"「ベトナムの呉朝成立」は何年？","answer":"939年","aliases":["939","西暦939年","西暦939","AD939","939AD","CE939","939CE"],"ex":"939年。前年の白藤江の戦い後、中国王朝からの自立が進んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200186,"topic":"year-186","title":"ベトナムの李朝成立","year":1009,"era":"中世","region":"sea","level":"標準","q":"「ベトナムの李朝成立」は何年？","answer":"1009年","aliases":["1009","西暦1009年","西暦1009","AD1009","1009AD","CE1009","1009CE"],"ex":"1009年。李公蘊が即位し、翌年に昇龍へ遷都した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200187,"topic":"year-187","title":"アノーヤターのタトン征服の伝統的年代","year":1057,"era":"中世","region":"sea","level":"発展","q":"「アノーヤターのタトン征服の伝統的年代」は何年？","answer":"1057年","aliases":["1057","西暦1057年","西暦1057","AD1057","1057AD","CE1057","1057CE"],"ex":"1057年。パガン王朝の拡大と上座部仏教の受容を結びつける。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200188,"topic":"year-188","title":"ベトナムの陳朝成立","year":1225,"era":"中世","region":"sea","level":"標準","q":"「ベトナムの陳朝成立」は何年？","answer":"1225年","aliases":["1225","西暦1225年","西暦1225","AD1225","1225AD","CE1225","1225CE"],"ex":"1225年。元軍の侵攻に抵抗した王朝としても重要。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200189,"topic":"year-189","title":"陳朝による白藤江での元軍撃退","year":1288,"era":"中世","region":"sea","level":"標準","q":"「陳朝による白藤江での元軍撃退」は何年？","answer":"1288年","aliases":["1288","西暦1288年","西暦1288","AD1288","1288AD","CE1288","1288CE"],"ex":"1288年。海上・河川交通とモンゴル勢力への抵抗を関連づける。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200190,"topic":"year-190","title":"マジャパヒト王国の成立","year":1293,"era":"中世","region":"sea","level":"標準","q":"「マジャパヒト王国の成立」は何年？","answer":"1293年","aliases":["1293","西暦1293年","西暦1293","AD1293","1293AD","CE1293","1293CE"],"ex":"1293年。ジャワ島で元軍撤退後に成立し、海域交易を背景に栄えた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200191,"topic":"year-191","title":"アユタヤ朝の成立","year":1351,"era":"中世","region":"sea","level":"標準","q":"「アユタヤ朝の成立」は何年？","answer":"1351年","aliases":["1351","西暦1351年","西暦1351","AD1351","1351AD","CE1351","1351CE"],"ex":"1351年。チャオプラヤ川流域を中心に発展したタイの王朝。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200192,"topic":"year-192","title":"ポルトガルによるマラッカ占領","year":1511,"era":"近世","region":"sea","level":"標準","q":"「ポルトガルによるマラッカ占領」は何年？","answer":"1511年","aliases":["1511","西暦1511年","西暦1511","AD1511","1511AD","CE1511","1511CE"],"ex":"1511年。東南アジアの海上交易の要地をおさえた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200193,"topic":"year-193","title":"スペインのフィリピン植民地支配開始","year":1565,"era":"近世","region":"sea","level":"標準","q":"「スペインのフィリピン植民地支配開始」は何年？","answer":"1565年","aliases":["1565","西暦1565年","西暦1565","AD1565","1565AD","CE1565","1565CE"],"ex":"1565年。レガスピがセブ島を拠点として支配を進めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200194,"topic":"year-194","title":"オランダ東インド会社の設立","year":1602,"era":"近世","region":"sea","level":"標準","q":"「オランダ東インド会社の設立」は何年？","answer":"1602年","aliases":["1602","西暦1602年","西暦1602","AD1602","1602AD","CE1602","1602CE"],"ex":"1602年。アジア交易の独占と植民地支配の拡大を担った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200195,"topic":"year-195","title":"オランダのバタヴィア建設","year":1619,"era":"近世","region":"sea","level":"標準","q":"「オランダのバタヴィア建設」は何年？","answer":"1619年","aliases":["1619","西暦1619年","西暦1619","AD1619","1619AD","CE1619","1619CE"],"ex":"1619年。現在のジャカルタにアジア交易・支配の拠点を置いた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200196,"topic":"year-196","title":"コンバウン朝軍によるペグー占領","year":1757,"era":"近世","region":"sea","level":"標準","q":"「コンバウン朝軍によるペグー占領」は何年？","answer":"1757年","aliases":["1757","西暦1757年","西暦1757","AD1757","1757AD","CE1757","1757CE"],"ex":"1757年。ビルマでコンバウン朝の勢力が拡大した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200197,"topic":"year-197","title":"アユタヤの陥落","year":1767,"era":"近世","region":"sea","level":"標準","q":"「アユタヤの陥落」は何年？","answer":"1767年","aliases":["1767","西暦1767年","西暦1767","AD1767","1767AD","CE1767","1767CE"],"ex":"1767年。ビルマ軍によって都が攻略され、アユタヤ朝が終わった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200198,"topic":"year-198","title":"タイのチャクリ朝成立","year":1782,"era":"近世","region":"sea","level":"標準","q":"「タイのチャクリ朝成立」は何年？","answer":"1782年","aliases":["1782","西暦1782年","西暦1782","AD1782","1782AD","CE1782","1782CE"],"ex":"1782年。ラーマ1世が即位し、バンコクを都とした。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200199,"topic":"year-199","title":"ベトナムの阮朝成立","year":1802,"era":"近代","region":"sea","level":"標準","q":"「ベトナムの阮朝成立」は何年？","answer":"1802年","aliases":["1802","西暦1802年","西暦1802","AD1802","1802AD","CE1802","1802CE"],"ex":"1802年。嘉隆帝が全国を統一し、フエを都とした。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200200,"topic":"year-200","title":"ラッフルズによるシンガポール拠点の設置","year":1819,"era":"近代","region":"sea","level":"標準","q":"「ラッフルズによるシンガポール拠点の設置」は何年？","answer":"1819年","aliases":["1819","西暦1819年","西暦1819","AD1819","1819AD","CE1819","1819CE"],"ex":"1819年。イギリスの海峡植民地支配と交易拠点化につながった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200201,"topic":"year-201","title":"イギリス＝オランダ条約","year":1824,"era":"近代","region":"sea","level":"標準","q":"「イギリス＝オランダ条約」は何年？","answer":"1824年","aliases":["1824","西暦1824年","西暦1824","AD1824","1824AD","CE1824","1824CE"],"ex":"1824年。マラッカ海峡周辺の両国の勢力圏が整理された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200202,"topic":"year-202","title":"フランス領インドシナ連邦の成立","year":1887,"era":"近代","region":"sea","level":"標準","q":"「フランス領インドシナ連邦の成立」は何年？","answer":"1887年","aliases":["1887","西暦1887年","西暦1887","AD1887","1887AD","CE1887","1887CE"],"ex":"1887年。ベトナムやカンボジアの植民地支配を統合した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200203,"topic":"year-203","title":"フィリピン革命の開始","year":1896,"era":"近代","region":"sea","level":"標準","q":"「フィリピン革命の開始」は何年？","answer":"1896年","aliases":["1896","西暦1896年","西暦1896","AD1896","1896AD","CE1896","1896CE"],"ex":"1896年。スペインからの独立を求める運動が武装蜂起へ発展した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200204,"topic":"year-204","title":"米西戦争とフィリピンの米国への割譲","year":1898,"era":"近代","region":"sea","level":"標準","q":"「米西戦争とフィリピンの米国への割譲」は何年？","answer":"1898年","aliases":["1898","西暦1898年","西暦1898","AD1898","1898AD","CE1898","1898CE"],"ex":"1898年。スペインの植民地支配が終わり、新たな対米関係が生まれた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200205,"topic":"year-205","title":"タイの立憲革命","year":1932,"era":"現代","region":"sea","level":"標準","q":"「タイの立憲革命」は何年？","answer":"1932年","aliases":["1932","西暦1932年","西暦1932","AD1932","1932AD","CE1932","1932CE"],"ex":"1932年。絶対王政から立憲体制への転換が図られた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200206,"topic":"year-206","title":"インドネシア独立宣言","year":1945,"era":"現代","region":"sea","level":"標準","q":"「インドネシア独立宣言」は何年？","answer":"1945年","aliases":["1945","西暦1945年","西暦1945","AD1945","1945AD","CE1945","1945CE"],"ex":"1945年。スカルノらが日本の降伏後に独立を宣言した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200207,"topic":"year-207","title":"ベトナム民主共和国の独立宣言","year":1945,"era":"現代","region":"sea","level":"標準","q":"「ベトナム民主共和国の独立宣言」は何年？","answer":"1945年","aliases":["1945","西暦1945年","西暦1945","AD1945","1945AD","CE1945","1945CE"],"ex":"1945年。ホー＝チ＝ミンがハノイで独立を宣言した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200208,"topic":"year-208","title":"フィリピン共和国の独立","year":1946,"era":"現代","region":"sea","level":"標準","q":"「フィリピン共和国の独立」は何年？","answer":"1946年","aliases":["1946","西暦1946年","西暦1946","AD1946","1946AD","CE1946","1946CE"],"ex":"1946年。アメリカから独立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200209,"topic":"year-209","title":"ビルマの独立","year":1948,"era":"現代","region":"sea","level":"標準","q":"「ビルマの独立」は何年？","answer":"1948年","aliases":["1948","西暦1948年","西暦1948","AD1948","1948AD","CE1948","1948CE"],"ex":"1948年。イギリスから独立し、現在のミャンマーへつながった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200210,"topic":"year-210","title":"ディエンビエンフーの戦い","year":1954,"era":"現代","region":"sea","level":"標準","q":"「ディエンビエンフーの戦い」は何年？","answer":"1954年","aliases":["1954","西暦1954年","西暦1954","AD1954","1954AD","CE1954","1954CE"],"ex":"1954年。ベトミンがフランス軍を破り、インドシナ戦争の転機となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200211,"topic":"year-211","title":"ジュネーヴ協定","year":1954,"era":"現代","region":"sea","level":"標準","q":"「ジュネーヴ協定」は何年？","answer":"1954年","aliases":["1954","西暦1954年","西暦1954","AD1954","1954AD","CE1954","1954CE"],"ex":"1954年。インドシナ戦争の停戦とベトナムの暫定的軍事分界を定めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200212,"topic":"year-212","title":"バンドン会議","year":1955,"era":"現代","region":"sea","level":"標準","q":"「バンドン会議」は何年？","answer":"1955年","aliases":["1955","西暦1955年","西暦1955","AD1955","1955AD","CE1955","1955CE"],"ex":"1955年。アジア・アフリカ諸国が反植民地主義などを確認した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200213,"topic":"year-213","title":"マラヤ連邦の独立","year":1957,"era":"現代","region":"sea","level":"標準","q":"「マラヤ連邦の独立」は何年？","answer":"1957年","aliases":["1957","西暦1957年","西暦1957","AD1957","1957AD","CE1957","1957CE"],"ex":"1957年。イギリスから独立し、のちマレーシアの中心となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200214,"topic":"year-214","title":"シンガポールの独立","year":1965,"era":"現代","region":"sea","level":"標準","q":"「シンガポールの独立」は何年？","answer":"1965年","aliases":["1965","西暦1965年","西暦1965","AD1965","1965AD","CE1965","1965CE"],"ex":"1965年。マレーシアから分離し、独立国家となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200215,"topic":"year-215","title":"ASEANの成立","year":1967,"era":"現代","region":"sea","level":"標準","q":"「ASEANの成立」は何年？","answer":"1967年","aliases":["1967","西暦1967年","西暦1967","AD1967","1967AD","CE1967","1967CE"],"ex":"1967年。東南アジア5か国がバンコク宣言によって設立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200216,"topic":"year-216","title":"ベトナム和平のパリ協定","year":1973,"era":"現代","region":"sea","level":"標準","q":"「ベトナム和平のパリ協定」は何年？","answer":"1973年","aliases":["1973","西暦1973年","西暦1973","AD1973","1973AD","CE1973","1973CE"],"ex":"1973年。アメリカ軍の撤退などを定めたが、戦闘は続いた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200217,"topic":"year-217","title":"サイゴン陥落","year":1975,"era":"現代","region":"sea","level":"標準","q":"「サイゴン陥落」は何年？","answer":"1975年","aliases":["1975","西暦1975年","西暦1975","AD1975","1975AD","CE1975","1975CE"],"ex":"1975年。南ベトナム政府が崩壊し、ベトナム戦争が終結した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200218,"topic":"year-218","title":"ベトナム社会主義共和国の成立","year":1976,"era":"現代","region":"sea","level":"標準","q":"「ベトナム社会主義共和国の成立」は何年？","answer":"1976年","aliases":["1976","西暦1976年","西暦1976","AD1976","1976AD","CE1976","1976CE"],"ex":"1976年。南北統一国家が正式に成立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200219,"topic":"year-219","title":"ヒジュラ","year":622,"era":"中世","region":"islam","level":"標準","q":"「ヒジュラ」は何年？","answer":"622年","aliases":["622","西暦622年","西暦622","AD622","622AD","CE622","622CE"],"ex":"622年。ムハンマドがメッカからメディナへ移住し、イスラーム暦の紀元となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200220,"topic":"year-220","title":"ムハンマドによるメッカ征服","year":630,"era":"中世","region":"islam","level":"標準","q":"「ムハンマドによるメッカ征服」は何年？","answer":"630年","aliases":["630","西暦630年","西暦630","AD630","630AD","CE630","630CE"],"ex":"630年。アラビア半島でイスラーム共同体の勢力が拡大した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200221,"topic":"year-221","title":"ムハンマドの死と正統カリフ時代の開始","year":632,"era":"中世","region":"islam","level":"標準","q":"「ムハンマドの死と正統カリフ時代の開始」は何年？","answer":"632年","aliases":["632","西暦632年","西暦632","AD632","632AD","CE632","632CE"],"ex":"632年。共同体の指導者をカリフが継承した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200222,"topic":"year-222","title":"ササン朝の滅亡","year":651,"era":"中世","region":"islam","level":"標準","q":"「ササン朝の滅亡」は何年？","answer":"651年","aliases":["651","西暦651年","西暦651","AD651","651AD","CE651","651CE"],"ex":"651年。アラブ＝イスラーム勢力の征服によって王朝が終わった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200223,"topic":"year-223","title":"ウマイヤ朝の成立","year":661,"era":"中世","region":"islam","level":"標準","q":"「ウマイヤ朝の成立」は何年？","answer":"661年","aliases":["661","西暦661年","西暦661","AD661","661AD","CE661","661CE"],"ex":"661年。ムアーウィヤがダマスクスを中心に世襲王朝を開いた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200224,"topic":"year-224","title":"イスラーム勢力のイベリア半島進出","year":711,"era":"中世","region":"islam","level":"標準","q":"「イスラーム勢力のイベリア半島進出」は何年？","answer":"711年","aliases":["711","西暦711年","西暦711","AD711","711AD","CE711","711CE"],"ex":"711年。ウマイヤ朝軍がジブラルタル海峡を渡った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200225,"topic":"year-225","title":"トゥール・ポワティエ間の戦い","year":732,"era":"中世","region":"islam","level":"標準","q":"「トゥール・ポワティエ間の戦い」は何年？","answer":"732年","aliases":["732","西暦732年","西暦732","AD732","732AD","CE732","732CE"],"ex":"732年。カール＝マルテルがイスラーム勢力を破った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200226,"topic":"year-226","title":"アッバース朝の成立","year":750,"era":"中世","region":"islam","level":"標準","q":"「アッバース朝の成立」は何年？","answer":"750年","aliases":["750","西暦750年","西暦750","AD750","750AD","CE750","750CE"],"ex":"750年。ウマイヤ朝に代わり、イスラーム世界の中心が東方へ移った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200227,"topic":"year-227","title":"後ウマイヤ朝の成立","year":756,"era":"中世","region":"islam","level":"標準","q":"「後ウマイヤ朝の成立」は何年？","answer":"756年","aliases":["756","西暦756年","西暦756","AD756","756AD","CE756","756CE"],"ex":"756年。イベリア半島でウマイヤ家の王朝が再建された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200228,"topic":"year-228","title":"バグダードの建設開始","year":762,"era":"中世","region":"islam","level":"標準","q":"「バグダードの建設開始」は何年？","answer":"762年","aliases":["762","西暦762年","西暦762","AD762","762AD","CE762","762CE"],"ex":"762年。アッバース朝のマンスールが新都の建設を進めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200229,"topic":"year-229","title":"ファーティマ朝の成立","year":909,"era":"中世","region":"islam","level":"標準","q":"「ファーティマ朝の成立」は何年？","answer":"909年","aliases":["909","西暦909年","西暦909","AD909","909AD","CE909","909CE"],"ex":"909年。北アフリカでシーア派の王朝が成立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200230,"topic":"year-230","title":"ガズナ朝成立の一般的な年代","year":962,"era":"中世","region":"islam","level":"発展","q":"「ガズナ朝成立の一般的な年代」は何年？","answer":"962年","aliases":["962","西暦962年","西暦962","AD962","962AD","CE962","962CE"],"ex":"962年。アフガニスタンを拠点に、のち北インドへ進出した。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200231,"topic":"year-231","title":"ファーティマ朝のエジプト征服","year":969,"era":"中世","region":"islam","level":"標準","q":"「ファーティマ朝のエジプト征服」は何年？","answer":"969年","aliases":["969","西暦969年","西暦969","AD969","969AD","CE969","969CE"],"ex":"969年。カイロを建設し、地中海東部へ勢力を拡大した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200232,"topic":"year-232","title":"セルジューク朝のバグダード入城","year":1055,"era":"中世","region":"islam","level":"標準","q":"「セルジューク朝のバグダード入城」は何年？","answer":"1055年","aliases":["1055","西暦1055年","西暦1055","AD1055","1055AD","CE1055","1055CE"],"ex":"1055年。トゥグリル＝ベクがアッバース朝カリフを保護下に置いた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200233,"topic":"year-233","title":"マンジケルトの戦い","year":1071,"era":"中世","region":"islam","level":"標準","q":"「マンジケルトの戦い」は何年？","answer":"1071年","aliases":["1071","西暦1071年","西暦1071","AD1071","1071AD","CE1071","1071CE"],"ex":"1071年。セルジューク朝がビザンツ帝国軍を破った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200234,"topic":"year-234","title":"サラディンのイェルサレム奪回","year":1187,"era":"中世","region":"islam","level":"標準","q":"「サラディンのイェルサレム奪回」は何年？","answer":"1187年","aliases":["1187","西暦1187年","西暦1187","AD1187","1187AD","CE1187","1187CE"],"ex":"1187年。第3回十字軍の契機となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200235,"topic":"year-235","title":"マムルーク朝の成立","year":1250,"era":"中世","region":"islam","level":"標準","q":"「マムルーク朝の成立」は何年？","answer":"1250年","aliases":["1250","西暦1250年","西暦1250","AD1250","1250AD","CE1250","1250CE"],"ex":"1250年。エジプトで軍人奴隷出身者の王朝が成立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200236,"topic":"year-236","title":"アイン＝ジャールートの戦い","year":1260,"era":"中世","region":"islam","level":"標準","q":"「アイン＝ジャールートの戦い」は何年？","answer":"1260年","aliases":["1260","西暦1260年","西暦1260","AD1260","1260AD","CE1260","1260CE"],"ex":"1260年。マムルーク軍がモンゴル軍の進撃を食い止めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200237,"topic":"year-237","title":"オスマン朝成立の伝統的な年代","year":1299,"era":"中世","region":"islam","level":"発展","q":"「オスマン朝成立の伝統的な年代」は何年？","answer":"1299年","aliases":["1299","西暦1299年","西暦1299","AD1299","1299AD","CE1299","1299CE"],"ex":"1299年。小アジアの君侯国から発展した王朝の起点として用いられる。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200238,"topic":"year-238","title":"モンゴル勢力の大都退去","year":1368,"era":"中世","region":"islam","level":"標準","q":"「モンゴル勢力の大都退去」は何年？","answer":"1368年","aliases":["1368","西暦1368年","西暦1368","AD1368","1368AD","CE1368","1368CE"],"ex":"1368年。明の北伐により元の宮廷が北方へ移った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200239,"topic":"year-239","title":"ティムールの即位","year":1370,"era":"中世","region":"islam","level":"発展","q":"「ティムールの即位」は何年？","answer":"1370年","aliases":["1370","西暦1370年","西暦1370","AD1370","1370AD","CE1370","1370CE"],"ex":"1370年。サマルカンドを中心に中央アジアの支配を拡大した。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200240,"topic":"year-240","title":"アンカラの戦い","year":1402,"era":"中世","region":"islam","level":"標準","q":"「アンカラの戦い」は何年？","answer":"1402年","aliases":["1402","西暦1402年","西暦1402","AD1402","1402AD","CE1402","1402CE"],"ex":"1402年。ティムールがオスマン朝のバヤジット1世を破った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200241,"topic":"year-241","title":"コンスタンティノープルの陥落","year":1453,"era":"中世","region":"islam","level":"標準","q":"「コンスタンティノープルの陥落」は何年？","answer":"1453年","aliases":["1453","西暦1453年","西暦1453","AD1453","1453AD","CE1453","1453CE"],"ex":"1453年。メフメト2世がビザンツ帝国の都を征服した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200242,"topic":"year-242","title":"サファヴィー朝の成立","year":1501,"era":"近世","region":"islam","level":"標準","q":"「サファヴィー朝の成立」は何年？","answer":"1501年","aliases":["1501","西暦1501年","西暦1501","AD1501","1501AD","CE1501","1501CE"],"ex":"1501年。イスマーイール1世が十二イマーム派を国教として定めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200243,"topic":"year-243","title":"チャルディラーンの戦い","year":1514,"era":"近世","region":"islam","level":"標準","q":"「チャルディラーンの戦い」は何年？","answer":"1514年","aliases":["1514","西暦1514年","西暦1514","AD1514","1514AD","CE1514","1514CE"],"ex":"1514年。オスマン朝がサファヴィー朝に勝利した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200244,"topic":"year-244","title":"スレイマン1世の即位","year":1520,"era":"近世","region":"islam","level":"発展","q":"「スレイマン1世の即位」は何年？","answer":"1520年","aliases":["1520","西暦1520年","西暦1520","AD1520","1520AD","CE1520","1520CE"],"ex":"1520年。オスマン帝国の最盛期を示す基準となる。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200245,"topic":"year-245","title":"モハーチの戦い","year":1526,"era":"近世","region":"islam","level":"標準","q":"「モハーチの戦い」は何年？","answer":"1526年","aliases":["1526","西暦1526年","西暦1526","AD1526","1526AD","CE1526","1526CE"],"ex":"1526年。オスマン軍がハンガリー軍を破った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200246,"topic":"year-246","title":"第1次ウィーン包囲","year":1529,"era":"近世","region":"islam","level":"標準","q":"「第1次ウィーン包囲」は何年？","answer":"1529年","aliases":["1529","西暦1529年","西暦1529","AD1529","1529AD","CE1529","1529CE"],"ex":"1529年。オスマン軍がハプスブルク家の都に迫った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200247,"topic":"year-247","title":"レパントの海戦","year":1571,"era":"近世","region":"islam","level":"標準","q":"「レパントの海戦」は何年？","answer":"1571年","aliases":["1571","西暦1571年","西暦1571","AD1571","1571AD","CE1571","1571CE"],"ex":"1571年。キリスト教諸国の連合艦隊がオスマン艦隊に勝利した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200248,"topic":"year-248","title":"第2次ウィーン包囲","year":1683,"era":"近世","region":"islam","level":"標準","q":"「第2次ウィーン包囲」は何年？","answer":"1683年","aliases":["1683","西暦1683年","西暦1683","AD1683","1683AD","CE1683","1683CE"],"ex":"1683年。オスマン軍が敗れ、ヨーロッパでの勢力後退につながった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200249,"topic":"year-249","title":"カルロヴィッツ条約","year":1699,"era":"近世","region":"islam","level":"標準","q":"「カルロヴィッツ条約」は何年？","answer":"1699年","aliases":["1699","西暦1699年","西暦1699","AD1699","1699AD","CE1699","1699CE"],"ex":"1699年。オスマン帝国がハンガリーの大部分などを失った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200250,"topic":"year-250","title":"ナポレオンのエジプト遠征","year":1798,"era":"近世","region":"islam","level":"標準","q":"「ナポレオンのエジプト遠征」は何年？","answer":"1798年","aliases":["1798","西暦1798年","西暦1798","AD1798","1798AD","CE1798","1798CE"],"ex":"1798年。フランスの東方進出とエジプトの変動を結びつける。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200251,"topic":"year-251","title":"ムハンマド＝アリーのエジプト総督就任","year":1805,"era":"近代","region":"islam","level":"標準","q":"「ムハンマド＝アリーのエジプト総督就任」は何年？","answer":"1805年","aliases":["1805","西暦1805年","西暦1805","AD1805","1805AD","CE1805","1805CE"],"ex":"1805年。軍制・産業改革を進め、オスマン朝からの自立を図った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200252,"topic":"year-252","title":"オスマン帝国のギュルハネ勅令","year":1839,"era":"近代","region":"islam","level":"発展","q":"「オスマン帝国のギュルハネ勅令」は何年？","answer":"1839年","aliases":["1839","西暦1839年","西暦1839","AD1839","1839AD","CE1839","1839CE"],"ex":"1839年。タンジマートと呼ばれる改革の出発点となった。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200253,"topic":"year-253","title":"オスマン帝国憲法の発布","year":1876,"era":"近代","region":"islam","level":"標準","q":"「オスマン帝国憲法の発布」は何年？","answer":"1876年","aliases":["1876","西暦1876年","西暦1876","AD1876","1876AD","CE1876","1876CE"],"ex":"1876年。ミドハト憲法とも呼ばれ、翌年に議会が開かれた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200254,"topic":"year-254","title":"青年トルコ革命","year":1908,"era":"近代","region":"islam","level":"標準","q":"「青年トルコ革命」は何年？","answer":"1908年","aliases":["1908","西暦1908年","西暦1908","AD1908","1908AD","CE1908","1908CE"],"ex":"1908年。停止されていた憲法と議会の復活を求めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200255,"topic":"year-255","title":"オスマン帝国のスルタン制廃止","year":1922,"era":"現代","region":"islam","level":"標準","q":"「オスマン帝国のスルタン制廃止」は何年？","answer":"1922年","aliases":["1922","西暦1922年","西暦1922","AD1922","1922AD","CE1922","1922CE"],"ex":"1922年。王朝支配が終わり、共和国成立へ向かった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200256,"topic":"year-256","title":"トルコ共和国の成立","year":1923,"era":"現代","region":"islam","level":"標準","q":"「トルコ共和国の成立」は何年？","answer":"1923年","aliases":["1923","西暦1923年","西暦1923","AD1923","1923AD","CE1923","1923CE"],"ex":"1923年。ムスタファ＝ケマルが初代大統領となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200257,"topic":"year-257","title":"トルコのカリフ制廃止","year":1924,"era":"現代","region":"islam","level":"標準","q":"「トルコのカリフ制廃止」は何年？","answer":"1924年","aliases":["1924","西暦1924年","西暦1924","AD1924","1924AD","CE1924","1924CE"],"ex":"1924年。世俗国家をめざす改革の重要な段階となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200258,"topic":"year-258","title":"サウジアラビア王国の成立","year":1932,"era":"現代","region":"islam","level":"標準","q":"「サウジアラビア王国の成立」は何年？","answer":"1932年","aliases":["1932","西暦1932年","西暦1932","AD1932","1932AD","CE1932","1932CE"],"ex":"1932年。イブン＝サウードがアラビア半島の支配を統合した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200259,"topic":"year-259","title":"イラン革命","year":1979,"era":"現代","region":"islam","level":"標準","q":"「イラン革命」は何年？","answer":"1979年","aliases":["1979","西暦1979年","西暦1979","AD1979","1979AD","CE1979","1979CE"],"ex":"1979年。パフレヴィー朝が倒れ、イスラーム共和国が成立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200260,"topic":"year-260","title":"アッシリアのニネヴェ陥落","year":-612,"era":"古代","region":"ancient","level":"標準","q":"「アッシリアのニネヴェ陥落」は何年？","answer":"前612年","aliases":["前612","紀元前612","紀元前612年","-612","BC612","612BC","BCE612","612BCE"],"ex":"前612年。新バビロニアとメディアの攻撃によって都が陥落した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200261,"topic":"year-261","title":"新バビロニアによるイェルサレム攻略","year":-586,"era":"古代","region":"ancient","level":"標準","q":"「新バビロニアによるイェルサレム攻略」は何年？","answer":"前586年","aliases":["前586","紀元前586","紀元前586年","-586","BC586","586BC","BCE586","586BCE"],"ex":"前586年。ユダ王国の滅亡とバビロン捕囚に結びつける。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200262,"topic":"year-262","title":"キュロス2世によるバビロン征服","year":-539,"era":"古代","region":"ancient","level":"標準","q":"「キュロス2世によるバビロン征服」は何年？","answer":"前539年","aliases":["前539","紀元前539","紀元前539年","-539","BC539","539BC","BCE539","539BCE"],"ex":"前539年。アケメネス朝ペルシアが西アジアを広く統合した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200263,"topic":"year-263","title":"カンビュセス2世のエジプト征服","year":-525,"era":"古代","region":"ancient","level":"標準","q":"「カンビュセス2世のエジプト征服」は何年？","answer":"前525年","aliases":["前525","紀元前525","紀元前525年","-525","BC525","525BC","BCE525","525BCE"],"ex":"前525年。アケメネス朝の支配がエジプトへ広がった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200264,"topic":"year-264","title":"ソロンの改革の一般的な年代","year":-594,"era":"古代","region":"ancient","level":"発展","q":"「ソロンの改革の一般的な年代」は何年？","answer":"前594年","aliases":["前594","紀元前594","紀元前594年","-594","BC594","594BC","BCE594","594BCE"],"ex":"前594年。アテネで負債奴隷の禁止などを進めた。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200265,"topic":"year-265","title":"クレイステネスの改革の一般的な年代","year":-508,"era":"古代","region":"ancient","level":"発展","q":"「クレイステネスの改革の一般的な年代」は何年？","answer":"前508年","aliases":["前508","紀元前508","紀元前508年","-508","BC508","508BC","BCE508","508BCE","前507","前507年","紀元前507年","-507"],"ex":"前508年。アテネ民主政の基礎を整えた。前508〜507年とする表記もある。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200266,"topic":"year-266","title":"マラトンの戦い","year":-490,"era":"古代","region":"ancient","level":"標準","q":"「マラトンの戦い」は何年？","answer":"前490年","aliases":["前490","紀元前490","紀元前490年","-490","BC490","490BC","BCE490","490BCE"],"ex":"前490年。アテネ軍がペルシア軍を撃退した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200267,"topic":"year-267","title":"サラミスの海戦","year":-480,"era":"古代","region":"ancient","level":"標準","q":"「サラミスの海戦」は何年？","answer":"前480年","aliases":["前480","紀元前480","紀元前480年","-480","BC480","480BC","BCE480","480BCE"],"ex":"前480年。ギリシア側艦隊がペルシア軍に勝利した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200268,"topic":"year-268","title":"プラタイアの戦い","year":-479,"era":"古代","region":"ancient","level":"標準","q":"「プラタイアの戦い」は何年？","answer":"前479年","aliases":["前479","紀元前479","紀元前479年","-479","BC479","479BC","BCE479","479BCE"],"ex":"前479年。ギリシア連合軍がペルシアの陸軍を破った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200269,"topic":"year-269","title":"デロス同盟の結成","year":-478,"era":"古代","region":"ancient","level":"標準","q":"「デロス同盟の結成」は何年？","answer":"前478年","aliases":["前478","紀元前478","紀元前478年","-478","BC478","478BC","BCE478","478BCE"],"ex":"前478年。アテネを盟主とする対ペルシア同盟が形成された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200270,"topic":"year-270","title":"ペロポネソス戦争の開始","year":-431,"era":"古代","region":"ancient","level":"標準","q":"「ペロポネソス戦争の開始」は何年？","answer":"前431年","aliases":["前431","紀元前431","紀元前431年","-431","BC431","431BC","BCE431","431BCE"],"ex":"前431年。アテネとスパルタを中心とする勢力が対立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200271,"topic":"year-271","title":"ペロポネソス戦争の終結","year":-404,"era":"古代","region":"ancient","level":"標準","q":"「ペロポネソス戦争の終結」は何年？","answer":"前404年","aliases":["前404","紀元前404","紀元前404年","-404","BC404","404BC","BCE404","404BCE"],"ex":"前404年。アテネが敗北し、スパルタの優位が確立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200272,"topic":"year-272","title":"カイロネイアの戦い","year":-338,"era":"古代","region":"ancient","level":"標準","q":"「カイロネイアの戦い」は何年？","answer":"前338年","aliases":["前338","紀元前338","紀元前338年","-338","BC338","338BC","BCE338","338BCE"],"ex":"前338年。フィリッポス2世がギリシア諸ポリスの連合軍を破った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200273,"topic":"year-273","title":"アレクサンドロスの東方遠征開始","year":-334,"era":"古代","region":"ancient","level":"標準","q":"「アレクサンドロスの東方遠征開始」は何年？","answer":"前334年","aliases":["前334","紀元前334","紀元前334年","-334","BC334","334BC","BCE334","334BCE"],"ex":"前334年。マケドニア軍がアジアへ渡り、ペルシア征服を進めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200274,"topic":"year-274","title":"ガウガメラの戦い","year":-331,"era":"古代","region":"ancient","level":"標準","q":"「ガウガメラの戦い」は何年？","answer":"前331年","aliases":["前331","紀元前331","紀元前331年","-331","BC331","331BC","BCE331","331BCE"],"ex":"前331年。アレクサンドロスがダレイオス3世の軍を破った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200275,"topic":"year-275","title":"アレクサンドロスの死","year":-323,"era":"古代","region":"ancient","level":"標準","q":"「アレクサンドロスの死」は何年？","answer":"前323年","aliases":["前323","紀元前323","紀元前323年","-323","BC323","323BC","BCE323","323BCE"],"ex":"前323年。後継者争いとヘレニズム諸王国の形成につながった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200276,"topic":"year-276","title":"ローマのホルテンシウス法","year":-287,"era":"古代","region":"ancient","level":"標準","q":"「ローマのホルテンシウス法」は何年？","answer":"前287年","aliases":["前287","紀元前287","紀元前287年","-287","BC287","287BC","BCE287","287BCE"],"ex":"前287年。平民会の決議が全ローマ市民を拘束することになった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200277,"topic":"year-277","title":"第1次ポエニ戦争の開始","year":-264,"era":"古代","region":"ancient","level":"標準","q":"「第1次ポエニ戦争の開始」は何年？","answer":"前264年","aliases":["前264","紀元前264","紀元前264年","-264","BC264","264BC","BCE264","264BCE"],"ex":"前264年。ローマとカルタゴがシチリア支配をめぐり争った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200278,"topic":"year-278","title":"第2次ポエニ戦争の開始","year":-218,"era":"古代","region":"ancient","level":"標準","q":"「第2次ポエニ戦争の開始」は何年？","answer":"前218年","aliases":["前218","紀元前218","紀元前218年","-218","BC218","218BC","BCE218","218BCE"],"ex":"前218年。ハンニバルのイタリア遠征と結びつける。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200279,"topic":"year-279","title":"カンネーの戦い","year":-216,"era":"古代","region":"ancient","level":"標準","q":"「カンネーの戦い」は何年？","answer":"前216年","aliases":["前216","紀元前216","紀元前216年","-216","BC216","216BC","BCE216","216BCE"],"ex":"前216年。ハンニバルがローマ軍を大敗させた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200280,"topic":"year-280","title":"ザマの戦い","year":-202,"era":"古代","region":"ancient","level":"標準","q":"「ザマの戦い」は何年？","answer":"前202年","aliases":["前202","紀元前202","紀元前202年","-202","BC202","202BC","BCE202","202BCE"],"ex":"前202年。スキピオがハンニバルを破り、ローマの優位が決まった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200281,"topic":"year-281","title":"カルタゴの滅亡","year":-146,"era":"古代","region":"ancient","level":"標準","q":"「カルタゴの滅亡」は何年？","answer":"前146年","aliases":["前146","紀元前146","紀元前146年","-146","BC146","146BC","BCE146","146BCE"],"ex":"前146年。第3次ポエニ戦争でローマ軍が都市を破壊した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200282,"topic":"year-282","title":"ティベリウス＝グラックスの改革","year":-133,"era":"古代","region":"ancient","level":"標準","q":"「ティベリウス＝グラックスの改革」は何年？","answer":"前133年","aliases":["前133","紀元前133","紀元前133年","-133","BC133","133BC","BCE133","133BCE"],"ex":"前133年。自作農の再建をめざしたが、元老院勢力と対立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200283,"topic":"year-283","title":"スパルタクスの反乱開始","year":-73,"era":"古代","region":"ancient","level":"標準","q":"「スパルタクスの反乱開始」は何年？","answer":"前73年","aliases":["前73","紀元前73","紀元前73年","-73","BC73","73BC","BCE73","73BCE"],"ex":"前73年。ローマの大規模な奴隷反乱として重要。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200284,"topic":"year-284","title":"第1回三頭政治の成立","year":-60,"era":"古代","region":"ancient","level":"標準","q":"「第1回三頭政治の成立」は何年？","answer":"前60年","aliases":["前60","紀元前60","紀元前60年","-60","BC60","60BC","BCE60","60BCE"],"ex":"前60年。カエサル・ポンペイウス・クラッススが政治協力した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200285,"topic":"year-285","title":"カエサルのルビコン渡河","year":-49,"era":"古代","region":"ancient","level":"標準","q":"「カエサルのルビコン渡河」は何年？","answer":"前49年","aliases":["前49","紀元前49","紀元前49年","-49","BC49","49BC","BCE49","49BCE"],"ex":"前49年。元老院・ポンペイウス側との内戦が始まった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200286,"topic":"year-286","title":"カエサルの暗殺","year":-44,"era":"古代","region":"ancient","level":"標準","q":"「カエサルの暗殺」は何年？","answer":"前44年","aliases":["前44","紀元前44","紀元前44年","-44","BC44","44BC","BCE44","44BCE"],"ex":"前44年。共和政回復を唱える勢力に殺され、再び内戦となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200287,"topic":"year-287","title":"アクティウムの海戦","year":-31,"era":"古代","region":"ancient","level":"標準","q":"「アクティウムの海戦」は何年？","answer":"前31年","aliases":["前31","紀元前31","紀元前31年","-31","BC31","31BC","BCE31","31BCE"],"ex":"前31年。オクタウィアヌスがアントニウスとクレオパトラの側に勝った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200288,"topic":"year-288","title":"オクタウィアヌスへのアウグストゥス称号授与","year":-27,"era":"古代","region":"ancient","level":"標準","q":"「オクタウィアヌスへのアウグストゥス称号授与」は何年？","answer":"前27年","aliases":["前27","紀元前27","紀元前27年","-27","BC27","27BC","BCE27","27BCE"],"ex":"前27年。ローマ帝政の始まりを示す一般的な画期。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200289,"topic":"year-289","title":"ヴェスヴィオ火山噴火とポンペイ埋没","year":79,"era":"古代","region":"ancient","level":"標準","q":"「ヴェスヴィオ火山噴火とポンペイ埋没」は何年？","answer":"79年","aliases":["79","西暦79年","西暦79","AD79","79AD","CE79","79CE"],"ex":"79年。ローマ都市の暮らしを伝える遺跡が残った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200290,"topic":"year-290","title":"カラカラ帝のローマ市民権拡大","year":212,"era":"古代","region":"ancient","level":"標準","q":"「カラカラ帝のローマ市民権拡大」は何年？","answer":"212年","aliases":["212","西暦212年","西暦212","AD212","212AD","CE212","212CE"],"ex":"212年。帝国内の自由民へ広く市民権が与えられた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200291,"topic":"year-291","title":"ディオクレティアヌスの即位","year":284,"era":"古代","region":"ancient","level":"発展","q":"「ディオクレティアヌスの即位」は何年？","answer":"284年","aliases":["284","西暦284年","西暦284","AD284","284AD","CE284","284CE"],"ex":"284年。専制君主政と帝国再編を結びつける。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200292,"topic":"year-292","title":"ミラノ勅令","year":313,"era":"古代","region":"ancient","level":"標準","q":"「ミラノ勅令」は何年？","answer":"313年","aliases":["313","西暦313年","西暦313","AD313","313AD","CE313","313CE"],"ex":"313年。コンスタンティヌスらがキリスト教公認の方針を示した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200293,"topic":"year-293","title":"ニケーア公会議","year":325,"era":"古代","region":"ancient","level":"標準","q":"「ニケーア公会議」は何年？","answer":"325年","aliases":["325","西暦325年","西暦325","AD325","325AD","CE325","325CE"],"ex":"325年。キリスト教の教義統一をめざして開かれた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200294,"topic":"year-294","title":"コンスタンティノープルへの遷都","year":330,"era":"古代","region":"ancient","level":"標準","q":"「コンスタンティノープルへの遷都」は何年？","answer":"330年","aliases":["330","西暦330年","西暦330","AD330","330AD","CE330","330CE"],"ex":"330年。ローマ帝国の新たな都がボスフォラス海峡に置かれた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200295,"topic":"year-295","title":"フン人の西進に伴うゲルマン人移動の画期","year":375,"era":"古代","region":"ancient","level":"標準","q":"「フン人の西進に伴うゲルマン人移動の画期」は何年？","answer":"375年","aliases":["375","西暦375年","西暦375","AD375","375AD","CE375","375CE"],"ex":"375年。民族移動は長期間にわたり、この年だけに起きた出来事ではない。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200296,"topic":"year-296","title":"テッサロニケ勅令","year":380,"era":"古代","region":"ancient","level":"標準","q":"「テッサロニケ勅令」は何年？","answer":"380年","aliases":["380","西暦380年","西暦380","AD380","380AD","CE380","380CE"],"ex":"380年。テオドシウス1世らがニケーア系キリスト教を帝国の正統宗教とした。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200297,"topic":"year-297","title":"ローマ帝国の東西分治固定化","year":395,"era":"古代","region":"ancient","level":"標準","q":"「ローマ帝国の東西分治固定化」は何年？","answer":"395年","aliases":["395","西暦395年","西暦395","AD395","395AD","CE395","395CE"],"ex":"395年。テオドシウス1世の死後、東西の皇帝による統治が続いた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200298,"topic":"year-298","title":"西ゴートによるローマ略奪","year":410,"era":"古代","region":"ancient","level":"標準","q":"「西ゴートによるローマ略奪」は何年？","answer":"410年","aliases":["410","西暦410年","西暦410","AD410","410AD","CE410","410CE"],"ex":"410年。アラリックの軍がローマ市を攻略した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200299,"topic":"year-299","title":"西ローマ皇帝の廃位","year":476,"era":"古代","region":"ancient","level":"標準","q":"「西ローマ皇帝の廃位」は何年？","answer":"476年","aliases":["476","西暦476年","西暦476","AD476","476AD","CE476","476CE"],"ex":"476年。オドアケルがロムルス＝アウグストゥルスを廃位した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200300,"topic":"year-300","title":"クローヴィスの即位","year":481,"era":"古代","region":"europe","level":"発展","q":"「クローヴィスの即位」は何年？","answer":"481年","aliases":["481","西暦481年","西暦481","AD481","481AD","CE481","481CE"],"ex":"481年。フランク王国の形成を進めたメロヴィング家の王。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200301,"topic":"year-301","title":"ユスティニアヌス帝の法典初版公布","year":529,"era":"中世","region":"europe","level":"発展","q":"「ユスティニアヌス帝の法典初版公布」は何年？","answer":"529年","aliases":["529","西暦529年","西暦529","AD529","529AD","CE529","529CE"],"ex":"529年。後のローマ法大全を構成する法典の編纂と結びつける。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200302,"topic":"year-302","title":"カール大帝の戴冠","year":800,"era":"中世","region":"europe","level":"標準","q":"「カール大帝の戴冠」は何年？","answer":"800年","aliases":["800","西暦800年","西暦800","AD800","800AD","CE800","800CE"],"ex":"800年。ローマ教皇レオ3世がフランク王に皇帝冠を授けた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200303,"topic":"year-303","title":"ヴェルダン条約","year":843,"era":"中世","region":"europe","level":"標準","q":"「ヴェルダン条約」は何年？","answer":"843年","aliases":["843","西暦843年","西暦843","AD843","843AD","CE843","843CE"],"ex":"843年。フランク王国が3つに分割された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200304,"topic":"year-304","title":"メルセン条約","year":870,"era":"中世","region":"europe","level":"標準","q":"「メルセン条約」は何年？","answer":"870年","aliases":["870","西暦870年","西暦870","AD870","870AD","CE870","870CE"],"ex":"870年。中部フランク領の一部が東西フランクに分割された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200305,"topic":"year-305","title":"オットー1世の皇帝戴冠","year":962,"era":"中世","region":"europe","level":"標準","q":"「オットー1世の皇帝戴冠」は何年？","answer":"962年","aliases":["962","西暦962年","西暦962","AD962","962AD","CE962","962CE"],"ex":"962年。神聖ローマ帝国の成立を示す一般的な画期。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200306,"topic":"year-306","title":"東西教会分裂の象徴的な年","year":1054,"era":"中世","region":"europe","level":"標準","q":"「東西教会分裂の象徴的な年」は何年？","answer":"1054年","aliases":["1054","西暦1054年","西暦1054","AD1054","1054AD","CE1054","1054CE"],"ex":"1054年。相互破門を経て、ローマとコンスタンティノープルの教会の隔たりが深まった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200307,"topic":"year-307","title":"ノルマン＝コンクェスト","year":1066,"era":"中世","region":"europe","level":"標準","q":"「ノルマン＝コンクェスト」は何年？","answer":"1066年","aliases":["1066","西暦1066年","西暦1066","AD1066","1066AD","CE1066","1066CE"],"ex":"1066年。ウィリアムがイングランドを征服した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200308,"topic":"year-308","title":"カノッサの屈辱","year":1077,"era":"中世","region":"europe","level":"標準","q":"「カノッサの屈辱」は何年？","answer":"1077年","aliases":["1077","西暦1077年","西暦1077","AD1077","1077AD","CE1077","1077CE"],"ex":"1077年。皇帝ハインリヒ4世が教皇グレゴリウス7世に赦しを求めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200309,"topic":"year-309","title":"クレルモン公会議での十字軍呼びかけ","year":1095,"era":"中世","region":"europe","level":"標準","q":"「クレルモン公会議での十字軍呼びかけ」は何年？","answer":"1095年","aliases":["1095","西暦1095年","西暦1095","AD1095","1095AD","CE1095","1095CE"],"ex":"1095年。教皇ウルバヌス2世が東方遠征を提唱した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200310,"topic":"year-310","title":"第1回十字軍の出発","year":1096,"era":"中世","region":"europe","level":"標準","q":"「第1回十字軍の出発」は何年？","answer":"1096年","aliases":["1096","西暦1096年","西暦1096","AD1096","1096AD","CE1096","1096CE"],"ex":"1096年。宗教・政治・経済の複数の動機を区別する。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200311,"topic":"year-311","title":"第1回十字軍によるイェルサレム占領","year":1099,"era":"中世","region":"europe","level":"標準","q":"「第1回十字軍によるイェルサレム占領」は何年？","answer":"1099年","aliases":["1099","西暦1099年","西暦1099","AD1099","1099AD","CE1099","1099CE"],"ex":"1099年。東地中海に十字軍国家がつくられた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200312,"topic":"year-312","title":"ヴォルムス協約","year":1122,"era":"中世","region":"europe","level":"標準","q":"「ヴォルムス協約」は何年？","answer":"1122年","aliases":["1122","西暦1122年","西暦1122","AD1122","1122AD","CE1122","1122CE"],"ex":"1122年。皇帝と教皇が聖職叙任権をめぐる対立に妥協を図った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200313,"topic":"year-313","title":"第4回十字軍のコンスタンティノープル占領","year":1204,"era":"中世","region":"europe","level":"標準","q":"「第4回十字軍のコンスタンティノープル占領」は何年？","answer":"1204年","aliases":["1204","西暦1204年","西暦1204","AD1204","1204AD","CE1204","1204CE"],"ex":"1204年。キリスト教勢力間の対立とラテン帝国成立を結びつける。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200314,"topic":"year-314","title":"マグナ＝カルタ","year":1215,"era":"中世","region":"europe","level":"標準","q":"「マグナ＝カルタ」は何年？","answer":"1215年","aliases":["1215","西暦1215年","西暦1215","AD1215","1215AD","CE1215","1215CE"],"ex":"1215年。イングランド王ジョンが貴族らの要求を受け入れた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200315,"topic":"year-315","title":"アッコン陥落","year":1291,"era":"中世","region":"europe","level":"標準","q":"「アッコン陥落」は何年？","answer":"1291年","aliases":["1291","西暦1291年","西暦1291","AD1291","1291AD","CE1291","1291CE"],"ex":"1291年。十字軍勢力の東地中海沿岸拠点が失われた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200316,"topic":"year-316","title":"フランスの三部会初開催","year":1302,"era":"中世","region":"europe","level":"標準","q":"「フランスの三部会初開催」は何年？","answer":"1302年","aliases":["1302","西暦1302年","西暦1302","AD1302","1302AD","CE1302","1302CE"],"ex":"1302年。フィリップ4世が教皇との対立の中で招集した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200317,"topic":"year-317","title":"教皇庁のアヴィニョン移転","year":1309,"era":"中世","region":"europe","level":"標準","q":"「教皇庁のアヴィニョン移転」は何年？","answer":"1309年","aliases":["1309","西暦1309年","西暦1309","AD1309","1309AD","CE1309","1309CE"],"ex":"1309年。フランス王権の影響が強い時期として整理する。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200318,"topic":"year-318","title":"百年戦争の開始","year":1337,"era":"中世","region":"europe","level":"標準","q":"「百年戦争の開始」は何年？","answer":"1337年","aliases":["1337","西暦1337年","西暦1337","AD1337","1337AD","CE1337","1337CE"],"ex":"1337年。イングランド王権とフランス王権が王位などをめぐり争った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200319,"topic":"year-319","title":"黒死病の西欧での大流行","year":1348,"era":"中世","region":"europe","level":"標準","q":"「黒死病の西欧での大流行」は何年？","answer":"1348年","aliases":["1348","西暦1348年","西暦1348","AD1348","1348AD","CE1348","1348CE"],"ex":"1348年。流行は複数年にわたり、労働力や社会構造を変えた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200320,"topic":"year-320","title":"神聖ローマ帝国の金印勅書","year":1356,"era":"中世","region":"europe","level":"標準","q":"「神聖ローマ帝国の金印勅書」は何年？","answer":"1356年","aliases":["1356","西暦1356年","西暦1356","AD1356","1356AD","CE1356","1356CE"],"ex":"1356年。皇帝選挙を行う7選帝侯の制度を定めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200321,"topic":"year-321","title":"ジャックリーの乱","year":1358,"era":"中世","region":"europe","level":"標準","q":"「ジャックリーの乱」は何年？","answer":"1358年","aliases":["1358","西暦1358年","西暦1358","AD1358","1358AD","CE1358","1358CE"],"ex":"1358年。百年戦争期のフランスで農民反乱が起きた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200322,"topic":"year-322","title":"教会大分裂の開始","year":1378,"era":"中世","region":"europe","level":"標準","q":"「教会大分裂の開始」は何年？","answer":"1378年","aliases":["1378","西暦1378年","西暦1378","AD1378","1378AD","CE1378","1378CE"],"ex":"1378年。ローマとアヴィニョンの教皇が並び立った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200323,"topic":"year-323","title":"ワット＝タイラーの乱","year":1381,"era":"中世","region":"europe","level":"標準","q":"「ワット＝タイラーの乱」は何年？","answer":"1381年","aliases":["1381","西暦1381年","西暦1381","AD1381","1381AD","CE1381","1381CE"],"ex":"1381年。イングランドの農民らが人頭税などに反対した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200324,"topic":"year-324","title":"コンスタンツ公会議の開会","year":1414,"era":"中世","region":"europe","level":"標準","q":"「コンスタンツ公会議の開会」は何年？","answer":"1414年","aliases":["1414","西暦1414年","西暦1414","AD1414","1414AD","CE1414","1414CE"],"ex":"1414年。教会大分裂の解消と宗教改革運動への対応をめざした。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200325,"topic":"year-325","title":"ヤン＝フスの処刑","year":1415,"era":"中世","region":"europe","level":"標準","q":"「ヤン＝フスの処刑」は何年？","answer":"1415年","aliases":["1415","西暦1415年","西暦1415","AD1415","1415AD","CE1415","1415CE"],"ex":"1415年。教会批判を続けたフスが公会議で異端とされ処刑された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200326,"topic":"year-326","title":"百年戦争の終結","year":1453,"era":"中世","region":"europe","level":"標準","q":"「百年戦争の終結」は何年？","answer":"1453年","aliases":["1453","西暦1453年","西暦1453","AD1453","1453AD","CE1453","1453CE"],"ex":"1453年。フランス王権がイングランド勢力をほぼ排除した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200327,"topic":"year-327","title":"ばら戦争の開始","year":1455,"era":"中世","region":"europe","level":"標準","q":"「ばら戦争の開始」は何年？","answer":"1455年","aliases":["1455","西暦1455年","西暦1455","AD1455","1455AD","CE1455","1455CE"],"ex":"1455年。ランカスター家とヨーク家が王位をめぐり争った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200328,"topic":"year-328","title":"チューダー朝の成立","year":1485,"era":"中世","region":"europe","level":"標準","q":"「チューダー朝の成立」は何年？","answer":"1485年","aliases":["1485","西暦1485年","西暦1485","AD1485","1485AD","CE1485","1485CE"],"ex":"1485年。ヘンリ7世が即位し、イングランド王権が再編された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200329,"topic":"year-329","title":"バルトロメウ＝ディアスのアフリカ南端到達","year":1488,"era":"中世","region":"europe","level":"標準","q":"「バルトロメウ＝ディアスのアフリカ南端到達」は何年？","answer":"1488年","aliases":["1488","西暦1488年","西暦1488","AD1488","1488AD","CE1488","1488CE"],"ex":"1488年。喜望峰を回るインド航路開拓の前段階となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200330,"topic":"year-330","title":"グラナダ陥落","year":1492,"era":"中世","region":"europe","level":"標準","q":"「グラナダ陥落」は何年？","answer":"1492年","aliases":["1492","西暦1492年","西暦1492","AD1492","1492AD","CE1492","1492CE"],"ex":"1492年。イベリア半島のナスル朝が滅び、レコンキスタが完了した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200331,"topic":"year-331","title":"コロンブスのカリブ海到達","year":1492,"era":"中世","region":"europe","level":"標準","q":"「コロンブスのカリブ海到達」は何年？","answer":"1492年","aliases":["1492","西暦1492年","西暦1492","AD1492","1492AD","CE1492","1492CE"],"ex":"1492年。アメリカ先住民社会とヨーロッパの持続的接触が始まった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200332,"topic":"year-332","title":"トルデシリャス条約","year":1494,"era":"中世","region":"europe","level":"標準","q":"「トルデシリャス条約」は何年？","answer":"1494年","aliases":["1494","西暦1494年","西暦1494","AD1494","1494AD","CE1494","1494CE"],"ex":"1494年。スペインとポルトガルが海外進出の境界を取り決めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200333,"topic":"year-333","title":"マゼラン艦隊の出航","year":1519,"era":"近世","region":"europe","level":"標準","q":"「マゼラン艦隊の出航」は何年？","answer":"1519年","aliases":["1519","西暦1519年","西暦1519","AD1519","1519AD","CE1519","1519CE"],"ex":"1519年。地球周航を達成する遠征が始まり、帰還は1522年。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200334,"topic":"year-334","title":"コルテスによるアステカ王国征服","year":1521,"era":"近世","region":"europe","level":"標準","q":"「コルテスによるアステカ王国征服」は何年？","answer":"1521年","aliases":["1521","西暦1521年","西暦1521","AD1521","1521AD","CE1521","1521CE"],"ex":"1521年。テノチティトラン陥落後、スペインの植民地支配が進んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200335,"topic":"year-335","title":"マゼラン艦隊の残存船の帰還","year":1522,"era":"近世","region":"europe","level":"標準","q":"「マゼラン艦隊の残存船の帰還」は何年？","answer":"1522年","aliases":["1522","西暦1522年","西暦1522","AD1522","1522AD","CE1522","1522CE"],"ex":"1522年。エルカノらが最初の世界周航を完了した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200336,"topic":"year-336","title":"ドイツ農民戦争の開始","year":1524,"era":"近世","region":"europe","level":"標準","q":"「ドイツ農民戦争の開始」は何年？","answer":"1524年","aliases":["1524","西暦1524年","西暦1524","AD1524","1524AD","CE1524","1524CE"],"ex":"1524年。宗教改革期の社会的要求が大規模反乱へ発展した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200337,"topic":"year-337","title":"ピサロによるクスコ占領","year":1533,"era":"近世","region":"europe","level":"標準","q":"「ピサロによるクスコ占領」は何年？","answer":"1533年","aliases":["1533","西暦1533年","西暦1533","AD1533","1533AD","CE1533","1533CE"],"ex":"1533年。インカ帝国の中心が攻略され、スペイン支配が進んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200338,"topic":"year-338","title":"イングランドの首長法","year":1534,"era":"近世","region":"europe","level":"標準","q":"「イングランドの首長法」は何年？","answer":"1534年","aliases":["1534","西暦1534年","西暦1534","AD1534","1534AD","CE1534","1534CE"],"ex":"1534年。ヘンリ8世をイングランド教会の首長とした。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200339,"topic":"year-339","title":"トリエント公会議の開会","year":1545,"era":"近世","region":"europe","level":"標準","q":"「トリエント公会議の開会」は何年？","answer":"1545年","aliases":["1545","西暦1545年","西暦1545","AD1545","1545AD","CE1545","1545CE"],"ex":"1545年。カトリック改革の方針が討議され、会議は断続的に続いた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200340,"topic":"year-340","title":"アウクスブルクの宗教和議","year":1555,"era":"近世","region":"europe","level":"標準","q":"「アウクスブルクの宗教和議」は何年？","answer":"1555年","aliases":["1555","西暦1555年","西暦1555","AD1555","1555AD","CE1555","1555CE"],"ex":"1555年。領邦君主によるカトリックかルター派の選択を認めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200341,"topic":"year-341","title":"エリザベス1世の即位","year":1558,"era":"近世","region":"europe","level":"発展","q":"「エリザベス1世の即位」は何年？","answer":"1558年","aliases":["1558","西暦1558年","西暦1558","AD1558","1558AD","CE1558","1558CE"],"ex":"1558年。イングランド国教会の確立と海外進出を結びつける。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200342,"topic":"year-342","title":"ネーデルラント独立戦争開始の一般的な年代","year":1568,"era":"近世","region":"europe","level":"発展","q":"「ネーデルラント独立戦争開始の一般的な年代」は何年？","answer":"1568年","aliases":["1568","西暦1568年","西暦1568","AD1568","1568AD","CE1568","1568CE"],"ex":"1568年。スペイン支配に対する反乱は複数段階を経て広がった。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200343,"topic":"year-343","title":"サン＝バルテルミの虐殺","year":1572,"era":"近世","region":"europe","level":"標準","q":"「サン＝バルテルミの虐殺」は何年？","answer":"1572年","aliases":["1572","西暦1572年","西暦1572","AD1572","1572AD","CE1572","1572CE"],"ex":"1572年。フランス宗教戦争期に多数のユグノーが殺された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200344,"topic":"year-344","title":"ユトレヒト同盟","year":1579,"era":"近世","region":"europe","level":"標準","q":"「ユトレヒト同盟」は何年？","answer":"1579年","aliases":["1579","西暦1579年","西暦1579","AD1579","1579AD","CE1579","1579CE"],"ex":"1579年。ネーデルラント北部諸州が結束した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200345,"topic":"year-345","title":"ネーデルラント連邦共和国のスペイン王廃位宣言","year":1581,"era":"近世","region":"europe","level":"標準","q":"「ネーデルラント連邦共和国のスペイン王廃位宣言」は何年？","answer":"1581年","aliases":["1581","西暦1581年","西暦1581","AD1581","1581AD","CE1581","1581CE"],"ex":"1581年。独立の国際的承認は1648年。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200346,"topic":"year-346","title":"アルマダ海戦","year":1588,"era":"近世","region":"europe","level":"標準","q":"「アルマダ海戦」は何年？","answer":"1588年","aliases":["1588","西暦1588年","西暦1588","AD1588","1588AD","CE1588","1588CE"],"ex":"1588年。スペインの無敵艦隊によるイングランド遠征が失敗した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200347,"topic":"year-347","title":"ナントの王令","year":1598,"era":"近世","region":"europe","level":"標準","q":"「ナントの王令」は何年？","answer":"1598年","aliases":["1598","西暦1598年","西暦1598","AD1598","1598AD","CE1598","1598CE"],"ex":"1598年。アンリ4世がユグノーに一定の信仰の自由を認めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200348,"topic":"year-348","title":"イギリス東インド会社の設立","year":1600,"era":"近世","region":"europe","level":"標準","q":"「イギリス東インド会社の設立」は何年？","answer":"1600年","aliases":["1600","西暦1600年","西暦1600","AD1600","1600AD","CE1600","1600CE"],"ex":"1600年。王室の特許を受け、アジア交易に参入した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200349,"topic":"year-349","title":"ロマノフ朝の成立","year":1613,"era":"近世","region":"europe","level":"標準","q":"「ロマノフ朝の成立」は何年？","answer":"1613年","aliases":["1613","西暦1613年","西暦1613","AD1613","1613AD","CE1613","1613CE"],"ex":"1613年。ミハイル＝ロマノフがロシア皇帝に選ばれた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200350,"topic":"year-350","title":"三十年戦争の開始","year":1618,"era":"近世","region":"europe","level":"標準","q":"「三十年戦争の開始」は何年？","answer":"1618年","aliases":["1618","西暦1618年","西暦1618","AD1618","1618AD","CE1618","1618CE"],"ex":"1618年。ベーメンの反乱からヨーロッパ規模の戦争へ拡大した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200351,"topic":"year-351","title":"イングランドの権利の請願","year":1628,"era":"近世","region":"europe","level":"標準","q":"「イングランドの権利の請願」は何年？","answer":"1628年","aliases":["1628","西暦1628年","西暦1628","AD1628","1628AD","CE1628","1628CE"],"ex":"1628年。議会が課税や身体拘束に関する権利を主張した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200352,"topic":"year-352","title":"イングランドの長期議会召集","year":1640,"era":"近世","region":"europe","level":"標準","q":"「イングランドの長期議会召集」は何年？","answer":"1640年","aliases":["1640","西暦1640年","西暦1640","AD1640","1640AD","CE1640","1640CE"],"ex":"1640年。国王と議会の対立が革命へつながった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200353,"topic":"year-353","title":"イングランド内戦の開始","year":1642,"era":"近世","region":"europe","level":"標準","q":"「イングランド内戦の開始」は何年？","answer":"1642年","aliases":["1642","西暦1642年","西暦1642","AD1642","1642AD","CE1642","1642CE"],"ex":"1642年。国王派と議会派が武力で争った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200354,"topic":"year-354","title":"チャールズ1世の処刑","year":1649,"era":"近世","region":"europe","level":"標準","q":"「チャールズ1世の処刑」は何年？","answer":"1649年","aliases":["1649","西暦1649年","西暦1649","AD1649","1649AD","CE1649","1649CE"],"ex":"1649年。イングランドで王政が廃止され、共和政が宣言された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200355,"topic":"year-355","title":"イングランドの航海法","year":1651,"era":"近世","region":"europe","level":"標準","q":"「イングランドの航海法」は何年？","answer":"1651年","aliases":["1651","西暦1651年","西暦1651","AD1651","1651AD","CE1651","1651CE"],"ex":"1651年。オランダの中継貿易に対抗する重商主義政策。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200356,"topic":"year-356","title":"イングランドの王政復古","year":1660,"era":"近世","region":"europe","level":"標準","q":"「イングランドの王政復古」は何年？","answer":"1660年","aliases":["1660","西暦1660年","西暦1660","AD1660","1660AD","CE1660","1660CE"],"ex":"1660年。チャールズ2世が王位に就いた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200357,"topic":"year-357","title":"ナントの王令廃止","year":1685,"era":"近世","region":"europe","level":"標準","q":"「ナントの王令廃止」は何年？","answer":"1685年","aliases":["1685","西暦1685年","西暦1685","AD1685","1685AD","CE1685","1685CE"],"ex":"1685年。ルイ14世のもとでユグノーの権利が奪われた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200358,"topic":"year-358","title":"イングランドの名誉革命","year":1688,"era":"近世","region":"europe","level":"標準","q":"「イングランドの名誉革命」は何年？","answer":"1688年","aliases":["1688","西暦1688年","西暦1688","AD1688","1688AD","CE1688","1688CE"],"ex":"1688年。ジェームズ2世が退位し、新たな王位継承が進んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200359,"topic":"year-359","title":"イングランドの権利の章典","year":1689,"era":"近世","region":"europe","level":"標準","q":"「イングランドの権利の章典」は何年？","answer":"1689年","aliases":["1689","西暦1689年","西暦1689","AD1689","1689AD","CE1689","1689CE"],"ex":"1689年。議会の権利を確認し、立憲君主政の基礎となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200360,"topic":"year-360","title":"スペイン継承戦争の開始","year":1701,"era":"近世","region":"europe","level":"標準","q":"「スペイン継承戦争の開始」は何年？","answer":"1701年","aliases":["1701","西暦1701年","西暦1701","AD1701","1701AD","CE1701","1701CE"],"ex":"1701年。スペイン王位の継承をめぐり列強が争った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200361,"topic":"year-361","title":"ロシアのサンクトペテルブルク建設開始","year":1703,"era":"近世","region":"europe","level":"標準","q":"「ロシアのサンクトペテルブルク建設開始」は何年？","answer":"1703年","aliases":["1703","西暦1703年","西暦1703","AD1703","1703AD","CE1703","1703CE"],"ex":"1703年。ピョートル1世の西欧化とバルト海進出を象徴する。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200362,"topic":"year-362","title":"グレートブリテン王国の成立","year":1707,"era":"近世","region":"europe","level":"標準","q":"「グレートブリテン王国の成立」は何年？","answer":"1707年","aliases":["1707","西暦1707年","西暦1707","AD1707","1707AD","CE1707","1707CE"],"ex":"1707年。イングランドとスコットランドが合同した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200363,"topic":"year-363","title":"ユトレヒト条約","year":1713,"era":"近世","region":"europe","level":"標準","q":"「ユトレヒト条約」は何年？","answer":"1713年","aliases":["1713","西暦1713年","西暦1713","AD1713","1713AD","CE1713","1713CE"],"ex":"1713年。スペイン継承戦争の主要な講和条約。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200364,"topic":"year-364","title":"オーストリア継承戦争の開始","year":1740,"era":"近世","region":"europe","level":"標準","q":"「オーストリア継承戦争の開始」は何年？","answer":"1740年","aliases":["1740","西暦1740年","西暦1740","AD1740","1740AD","CE1740","1740CE"],"ex":"1740年。マリア＝テレジアの継承と諸国の領土要求が対立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200365,"topic":"year-365","title":"七年戦争の開始","year":1756,"era":"近世","region":"europe","level":"標準","q":"「七年戦争の開始」は何年？","answer":"1756年","aliases":["1756","西暦1756年","西暦1756","AD1756","1756AD","CE1756","1756CE"],"ex":"1756年。ヨーロッパと植民地で列強間の戦争が展開された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200366,"topic":"year-366","title":"七年戦争を終えるパリ条約","year":1763,"era":"近世","region":"europe","level":"標準","q":"「七年戦争を終えるパリ条約」は何年？","answer":"1763年","aliases":["1763","西暦1763年","西暦1763","AD1763","1763AD","CE1763","1763CE"],"ex":"1763年。イギリスの北米・インドでの優位が強まった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200367,"topic":"year-367","title":"第1回ポーランド分割","year":1772,"era":"近世","region":"europe","level":"標準","q":"「第1回ポーランド分割」は何年？","answer":"1772年","aliases":["1772","西暦1772年","西暦1772","AD1772","1772AD","CE1772","1772CE"],"ex":"1772年。ロシア・プロイセン・オーストリアが領土を分割した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200368,"topic":"year-368","title":"ボストン茶会事件","year":1773,"era":"近世","region":"europe","level":"標準","q":"「ボストン茶会事件」は何年？","answer":"1773年","aliases":["1773","西暦1773年","西暦1773","AD1773","1773AD","CE1773","1773CE"],"ex":"1773年。イギリス本国と北米植民地の対立が激化した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200369,"topic":"year-369","title":"アメリカ独立戦争の開始","year":1775,"era":"近世","region":"europe","level":"標準","q":"「アメリカ独立戦争の開始」は何年？","answer":"1775年","aliases":["1775","西暦1775年","西暦1775","AD1775","1775AD","CE1775","1775CE"],"ex":"1775年。レキシントン・コンコードで武力衝突が起きた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200370,"topic":"year-370","title":"アメリカ独立を承認したパリ条約","year":1783,"era":"近世","region":"europe","level":"標準","q":"「アメリカ独立を承認したパリ条約」は何年？","answer":"1783年","aliases":["1783","西暦1783年","西暦1783","AD1783","1783AD","CE1783","1783CE"],"ex":"1783年。イギリスが13植民地の独立を正式に認めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200371,"topic":"year-371","title":"アメリカ合衆国憲法の制定","year":1787,"era":"近世","region":"europe","level":"標準","q":"「アメリカ合衆国憲法の制定」は何年？","answer":"1787年","aliases":["1787","西暦1787年","西暦1787","AD1787","1787AD","CE1787","1787CE"],"ex":"1787年。連邦制や三権分立の枠組みを定めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200372,"topic":"year-372","title":"フランス初の成文憲法","year":1791,"era":"近世","region":"europe","level":"標準","q":"「フランス初の成文憲法」は何年？","answer":"1791年","aliases":["1791","西暦1791年","西暦1791","AD1791","1791AD","CE1791","1791CE"],"ex":"1791年。立憲君主政を定めたが、政治対立は続いた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200373,"topic":"year-373","title":"フランス第1共和政の成立","year":1792,"era":"近世","region":"europe","level":"標準","q":"「フランス第1共和政の成立」は何年？","answer":"1792年","aliases":["1792","西暦1792年","西暦1792","AD1792","1792AD","CE1792","1792CE"],"ex":"1792年。王政が廃止され、国民公会が共和政を宣言した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200374,"topic":"year-374","title":"ルイ16世の処刑","year":1793,"era":"近世","region":"europe","level":"標準","q":"「ルイ16世の処刑」は何年？","answer":"1793年","aliases":["1793","西暦1793年","西暦1793","AD1793","1793AD","CE1793","1793CE"],"ex":"1793年。革命期の対外戦争と国内の政治対立が激化した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200375,"topic":"year-375","title":"テルミドールのクーデタ","year":1794,"era":"近世","region":"europe","level":"標準","q":"「テルミドールのクーデタ」は何年？","answer":"1794年","aliases":["1794","西暦1794年","西暦1794","AD1794","1794AD","CE1794","1794CE"],"ex":"1794年。ロベスピエールらが失脚し、恐怖政治が終わりに向かった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200376,"topic":"year-376","title":"第3回ポーランド分割","year":1795,"era":"近世","region":"europe","level":"標準","q":"「第3回ポーランド分割」は何年？","answer":"1795年","aliases":["1795","西暦1795年","西暦1795","AD1795","1795AD","CE1795","1795CE"],"ex":"1795年。ポーランド国家が地図上から姿を消した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200377,"topic":"year-377","title":"ブリュメール18日のクーデタ","year":1799,"era":"近世","region":"europe","level":"標準","q":"「ブリュメール18日のクーデタ」は何年？","answer":"1799年","aliases":["1799","西暦1799年","西暦1799","AD1799","1799AD","CE1799","1799CE"],"ex":"1799年。ナポレオンが統領政府を樹立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200378,"topic":"year-378","title":"ナポレオンの皇帝即位","year":1804,"era":"近代","region":"europe","level":"発展","q":"「ナポレオンの皇帝即位」は何年？","answer":"1804年","aliases":["1804","西暦1804年","西暦1804","AD1804","1804AD","CE1804","1804CE"],"ex":"1804年。フランス第1帝政が始まった。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200379,"topic":"year-379","title":"ナポレオン法典の公布","year":1804,"era":"近代","region":"europe","level":"標準","q":"「ナポレオン法典の公布」は何年？","answer":"1804年","aliases":["1804","西暦1804年","西暦1804","AD1804","1804AD","CE1804","1804CE"],"ex":"1804年。私有財産や法の前の平等などを制度化した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200380,"topic":"year-380","title":"トラファルガーの海戦","year":1805,"era":"近代","region":"europe","level":"標準","q":"「トラファルガーの海戦」は何年？","answer":"1805年","aliases":["1805","西暦1805年","西暦1805","AD1805","1805AD","CE1805","1805CE"],"ex":"1805年。ネルソン指揮のイギリス艦隊が仏西連合艦隊を破った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200381,"topic":"year-381","title":"ナポレオンの大陸封鎖令","year":1806,"era":"近代","region":"europe","level":"標準","q":"「ナポレオンの大陸封鎖令」は何年？","answer":"1806年","aliases":["1806","西暦1806年","西暦1806","AD1806","1806AD","CE1806","1806CE"],"ex":"1806年。イギリスとの通商を禁じ、その経済力に対抗しようとした。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200382,"topic":"year-382","title":"ナポレオンのロシア遠征","year":1812,"era":"近代","region":"europe","level":"標準","q":"「ナポレオンのロシア遠征」は何年？","answer":"1812年","aliases":["1812","西暦1812年","西暦1812","AD1812","1812AD","CE1812","1812CE"],"ex":"1812年。補給難などから大敗し、帝国の衰退が進んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200383,"topic":"year-383","title":"ウィーン会議の開会","year":1814,"era":"近代","region":"europe","level":"標準","q":"「ウィーン会議の開会」は何年？","answer":"1814年","aliases":["1814","西暦1814年","西暦1814","AD1814","1814AD","CE1814","1814CE"],"ex":"1814年。ナポレオン戦争後のヨーロッパ秩序が討議された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200384,"topic":"year-384","title":"ワーテルローの戦い","year":1815,"era":"近代","region":"europe","level":"標準","q":"「ワーテルローの戦い」は何年？","answer":"1815年","aliases":["1815","西暦1815年","西暦1815","AD1815","1815AD","CE1815","1815CE"],"ex":"1815年。ナポレオンが最終的に敗れ、復古秩序が固まった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200385,"topic":"year-385","title":"ハイチ独立","year":1804,"era":"近代","region":"modern","level":"標準","q":"「ハイチ独立」は何年？","answer":"1804年","aliases":["1804","西暦1804年","西暦1804","AD1804","1804AD","CE1804","1804CE"],"ex":"1804年。奴隷解放運動とフランスからの独立が結びついた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200386,"topic":"year-386","title":"メキシコ独立運動の開始","year":1810,"era":"近代","region":"modern","level":"標準","q":"「メキシコ独立運動の開始」は何年？","answer":"1810年","aliases":["1810","西暦1810年","西暦1810","AD1810","1810AD","CE1810","1810CE"],"ex":"1810年。イダルゴの蜂起を画期とし、独立達成は1821年。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200387,"topic":"year-387","title":"ギリシア独立戦争の開始","year":1821,"era":"近代","region":"modern","level":"標準","q":"「ギリシア独立戦争の開始」は何年？","answer":"1821年","aliases":["1821","西暦1821年","西暦1821","AD1821","1821AD","CE1821","1821CE"],"ex":"1821年。オスマン帝国からの独立を求める運動が始まった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200388,"topic":"year-388","title":"ブラジル独立宣言","year":1822,"era":"近代","region":"modern","level":"標準","q":"「ブラジル独立宣言」は何年？","answer":"1822年","aliases":["1822","西暦1822年","西暦1822","AD1822","1822AD","CE1822","1822CE"],"ex":"1822年。ポルトガルから独立し、当初は帝政をとった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200389,"topic":"year-389","title":"モンロー宣言","year":1823,"era":"近代","region":"modern","level":"標準","q":"「モンロー宣言」は何年？","answer":"1823年","aliases":["1823","西暦1823年","西暦1823","AD1823","1823AD","CE1823","1823CE"],"ex":"1823年。アメリカ合衆国がヨーロッパとアメリカ大陸の相互不干渉を唱えた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200390,"topic":"year-390","title":"ロシアのデカブリストの反乱","year":1825,"era":"近代","region":"modern","level":"標準","q":"「ロシアのデカブリストの反乱」は何年？","answer":"1825年","aliases":["1825","西暦1825年","西暦1825","AD1825","1825AD","CE1825","1825CE"],"ex":"1825年。皇帝継承期に将校らが専制政治への改革を求めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200391,"topic":"year-391","title":"フランス七月革命","year":1830,"era":"近代","region":"modern","level":"標準","q":"「フランス七月革命」は何年？","answer":"1830年","aliases":["1830","西暦1830年","西暦1830","AD1830","1830AD","CE1830","1830CE"],"ex":"1830年。ブルボン朝が倒れ、ルイ＝フィリップの七月王政となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200392,"topic":"year-392","title":"イギリス第1回選挙法改正","year":1832,"era":"近代","region":"modern","level":"標準","q":"「イギリス第1回選挙法改正」は何年？","answer":"1832年","aliases":["1832","西暦1832年","西暦1832","AD1832","1832AD","CE1832","1832CE"],"ex":"1832年。産業資本家らの政治参加が拡大した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200393,"topic":"year-393","title":"ドイツ関税同盟の発足","year":1834,"era":"近代","region":"modern","level":"標準","q":"「ドイツ関税同盟の発足」は何年？","answer":"1834年","aliases":["1834","西暦1834年","西暦1834","AD1834","1834AD","CE1834","1834CE"],"ex":"1834年。プロイセンを中心とする経済統合が進んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200394,"topic":"year-394","title":"イギリスの人民憲章発表","year":1838,"era":"近代","region":"modern","level":"標準","q":"「イギリスの人民憲章発表」は何年？","answer":"1838年","aliases":["1838","西暦1838年","西暦1838","AD1838","1838AD","CE1838","1838CE"],"ex":"1838年。チャーティスト運動が普通選挙などを求めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200395,"topic":"year-395","title":"イギリスの穀物法廃止","year":1846,"era":"近代","region":"modern","level":"標準","q":"「イギリスの穀物法廃止」は何年？","answer":"1846年","aliases":["1846","西暦1846年","西暦1846","AD1846","1846AD","CE1846","1846CE"],"ex":"1846年。自由貿易政策への転換を象徴する。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200396,"topic":"year-396","title":"フランス二月革命","year":1848,"era":"近代","region":"modern","level":"標準","q":"「フランス二月革命」は何年？","answer":"1848年","aliases":["1848","西暦1848年","西暦1848","AD1848","1848AD","CE1848","1848CE"],"ex":"1848年。七月王政が倒れ、第2共和政が成立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200397,"topic":"year-397","title":"フランクフルト国民議会の開会","year":1848,"era":"近代","region":"modern","level":"標準","q":"「フランクフルト国民議会の開会」は何年？","answer":"1848年","aliases":["1848","西暦1848年","西暦1848","AD1848","1848AD","CE1848","1848CE"],"ex":"1848年。ドイツ統一と憲法制定をめざした。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200398,"topic":"year-398","title":"フランス第2帝政の成立","year":1852,"era":"近代","region":"modern","level":"標準","q":"「フランス第2帝政の成立」は何年？","answer":"1852年","aliases":["1852","西暦1852年","西暦1852","AD1852","1852AD","CE1852","1852CE"],"ex":"1852年。ナポレオン3世が皇帝となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200399,"topic":"year-399","title":"クリミア戦争の開始","year":1853,"era":"近代","region":"modern","level":"標準","q":"「クリミア戦争の開始」は何年？","answer":"1853年","aliases":["1853","西暦1853年","西暦1853","AD1853","1853AD","CE1853","1853CE"],"ex":"1853年。ロシアとオスマン帝国の対立に英仏などが介入した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200400,"topic":"year-400","title":"クリミア戦争を終えるパリ条約","year":1856,"era":"近代","region":"modern","level":"標準","q":"「クリミア戦争を終えるパリ条約」は何年？","answer":"1856年","aliases":["1856","西暦1856年","西暦1856","AD1856","1856AD","CE1856","1856CE"],"ex":"1856年。ロシアの黒海での軍事活動が制限された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200401,"topic":"year-401","title":"イタリア統一戦争の開始","year":1859,"era":"近代","region":"modern","level":"標準","q":"「イタリア統一戦争の開始」は何年？","answer":"1859年","aliases":["1859","西暦1859年","西暦1859","AD1859","1859AD","CE1859","1859CE"],"ex":"1859年。サルデーニャ王国がフランスと協力し、オーストリアと戦った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200402,"topic":"year-402","title":"イタリア王国の成立","year":1861,"era":"近代","region":"modern","level":"標準","q":"「イタリア王国の成立」は何年？","answer":"1861年","aliases":["1861","西暦1861年","西暦1861","AD1861","1861AD","CE1861","1861CE"],"ex":"1861年。ヴィットーリオ＝エマヌエーレ2世が国王となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200403,"topic":"year-403","title":"ロシアの農奴解放令","year":1861,"era":"近代","region":"modern","level":"標準","q":"「ロシアの農奴解放令」は何年？","answer":"1861年","aliases":["1861","西暦1861年","西暦1861","AD1861","1861AD","CE1861","1861CE"],"ex":"1861年。アレクサンドル2世が改革を進めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200404,"topic":"year-404","title":"アメリカ南北戦争の開始","year":1861,"era":"近代","region":"modern","level":"標準","q":"「アメリカ南北戦争の開始」は何年？","answer":"1861年","aliases":["1861","西暦1861年","西暦1861","AD1861","1861AD","CE1861","1861CE"],"ex":"1861年。奴隷制や連邦のあり方をめぐる対立が内戦になった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200405,"topic":"year-405","title":"アメリカの奴隷解放宣言の発効","year":1863,"era":"近代","region":"modern","level":"標準","q":"「アメリカの奴隷解放宣言の発効」は何年？","answer":"1863年","aliases":["1863","西暦1863年","西暦1863","AD1863","1863AD","CE1863","1863CE"],"ex":"1863年。リンカンの宣言が反乱地域の奴隷の解放を掲げた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200406,"topic":"year-406","title":"第1インターナショナルの成立","year":1864,"era":"近代","region":"modern","level":"標準","q":"「第1インターナショナルの成立」は何年？","answer":"1864年","aliases":["1864","西暦1864年","西暦1864","AD1864","1864AD","CE1864","1864CE"],"ex":"1864年。労働者の国際的連帯をめざす組織がロンドンで発足した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200407,"topic":"year-407","title":"普墺戦争","year":1866,"era":"近代","region":"modern","level":"標準","q":"「普墺戦争」は何年？","answer":"1866年","aliases":["1866","西暦1866年","西暦1866","AD1866","1866AD","CE1866","1866CE"],"ex":"1866年。プロイセンが勝利し、ドイツ統一の主導権を握った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200408,"topic":"year-408","title":"オーストリア＝ハンガリー二重帝国の成立","year":1867,"era":"近代","region":"modern","level":"標準","q":"「オーストリア＝ハンガリー二重帝国の成立」は何年？","answer":"1867年","aliases":["1867","西暦1867年","西暦1867","AD1867","1867AD","CE1867","1867CE"],"ex":"1867年。アウスグライヒによって二重国家が形成された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200409,"topic":"year-409","title":"スエズ運河の開通","year":1869,"era":"近代","region":"modern","level":"標準","q":"「スエズ運河の開通」は何年？","answer":"1869年","aliases":["1869","西暦1869年","西暦1869","AD1869","1869AD","CE1869","1869CE"],"ex":"1869年。地中海と紅海を結び、世界の海上交通を変えた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200410,"topic":"year-410","title":"普仏戦争の開始","year":1870,"era":"近代","region":"modern","level":"標準","q":"「普仏戦争の開始」は何年？","answer":"1870年","aliases":["1870","西暦1870年","西暦1870","AD1870","1870AD","CE1870","1870CE"],"ex":"1870年。プロイセンとフランスの戦争がドイツ統一を促した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200411,"topic":"year-411","title":"ドイツ帝国の成立","year":1871,"era":"近代","region":"modern","level":"標準","q":"「ドイツ帝国の成立」は何年？","answer":"1871年","aliases":["1871","西暦1871年","西暦1871","AD1871","1871AD","CE1871","1871CE"],"ex":"1871年。ヴェルサイユでヴィルヘルム1世が皇帝となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200412,"topic":"year-412","title":"パリ＝コミューン","year":1871,"era":"近代","region":"modern","level":"標準","q":"「パリ＝コミューン」は何年？","answer":"1871年","aliases":["1871","西暦1871年","西暦1871","AD1871","1871AD","CE1871","1871CE"],"ex":"1871年。普仏戦争後のパリで自治政権が成立し、軍に鎮圧された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200413,"topic":"year-413","title":"ベルリン会議","year":1878,"era":"近代","region":"modern","level":"標準","q":"「ベルリン会議」は何年？","answer":"1878年","aliases":["1878","西暦1878年","西暦1878","AD1878","1878AD","CE1878","1878CE"],"ex":"1878年。バルカン問題をめぐり列強がサン＝ステファノ条約を修正した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200414,"topic":"year-414","title":"三国同盟の成立","year":1882,"era":"近代","region":"modern","level":"標準","q":"「三国同盟の成立」は何年？","answer":"1882年","aliases":["1882","西暦1882年","西暦1882","AD1882","1882AD","CE1882","1882CE"],"ex":"1882年。ドイツ・オーストリア＝ハンガリー・イタリアが同盟した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200415,"topic":"year-415","title":"ベルリン＝アフリカ会議の開会","year":1884,"era":"近代","region":"modern","level":"標準","q":"「ベルリン＝アフリカ会議の開会」は何年？","answer":"1884年","aliases":["1884","西暦1884年","西暦1884","AD1884","1884AD","CE1884","1884CE"],"ex":"1884年。1885年まで開かれ、植民地獲得の原則などが討議された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200416,"topic":"year-416","title":"露仏同盟の成立","year":1894,"era":"近代","region":"modern","level":"標準","q":"「露仏同盟の成立」は何年？","answer":"1894年","aliases":["1894","西暦1894年","西暦1894","AD1894","1894AD","CE1894","1894CE"],"ex":"1894年。フランスとロシアがドイツに対抗する協力関係を築いた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200417,"topic":"year-417","title":"ファショダ事件","year":1898,"era":"近代","region":"modern","level":"標準","q":"「ファショダ事件」は何年？","answer":"1898年","aliases":["1898","西暦1898年","西暦1898","AD1898","1898AD","CE1898","1898CE"],"ex":"1898年。アフリカでイギリスとフランスの植民地政策が衝突した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200418,"topic":"year-418","title":"南アフリカ戦争の開始","year":1899,"era":"近代","region":"modern","level":"標準","q":"「南アフリカ戦争の開始」は何年？","answer":"1899年","aliases":["1899","西暦1899年","西暦1899","AD1899","1899AD","CE1899","1899CE"],"ex":"1899年。イギリスとブール人の共和国が戦った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200419,"topic":"year-419","title":"日英同盟の締結","year":1902,"era":"近代","region":"modern","level":"標準","q":"「日英同盟の締結」は何年？","answer":"1902年","aliases":["1902","西暦1902年","西暦1902","AD1902","1902AD","CE1902","1902CE"],"ex":"1902年。東アジアでの利害とロシアへの対抗を背景に結ばれた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200420,"topic":"year-420","title":"英仏協商の成立","year":1904,"era":"近代","region":"modern","level":"標準","q":"「英仏協商の成立」は何年？","answer":"1904年","aliases":["1904","西暦1904年","西暦1904","AD1904","1904AD","CE1904","1904CE"],"ex":"1904年。植民地問題の調整が両国の接近につながった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200421,"topic":"year-421","title":"日露戦争の開始","year":1904,"era":"近代","region":"modern","level":"標準","q":"「日露戦争の開始」は何年？","answer":"1904年","aliases":["1904","西暦1904年","西暦1904","AD1904","1904AD","CE1904","1904CE"],"ex":"1904年。満州・朝鮮をめぐる日露の対立が戦争に発展した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200422,"topic":"year-422","title":"ロシア第1革命","year":1905,"era":"近代","region":"modern","level":"標準","q":"「ロシア第1革命」は何年？","answer":"1905年","aliases":["1905","西暦1905年","西暦1905","AD1905","1905AD","CE1905","1905CE"],"ex":"1905年。血の日曜日事件などを契機に皇帝への改革要求が広がった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200423,"topic":"year-423","title":"ポーツマス条約","year":1905,"era":"近代","region":"modern","level":"標準","q":"「ポーツマス条約」は何年？","answer":"1905年","aliases":["1905","西暦1905年","西暦1905","AD1905","1905AD","CE1905","1905CE"],"ex":"1905年。日露戦争の講和条約で、日本の韓国での優越などを認めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200424,"topic":"year-424","title":"英露協商の成立","year":1907,"era":"近代","region":"modern","level":"標準","q":"「英露協商の成立」は何年？","answer":"1907年","aliases":["1907","西暦1907年","西暦1907","AD1907","1907AD","CE1907","1907CE"],"ex":"1907年。英仏協商・露仏同盟とあわせ、三国協商の枠組みができた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200425,"topic":"year-425","title":"第1次バルカン戦争の開始","year":1912,"era":"近代","region":"modern","level":"標準","q":"「第1次バルカン戦争の開始」は何年？","answer":"1912年","aliases":["1912","西暦1912年","西暦1912","AD1912","1912AD","CE1912","1912CE"],"ex":"1912年。バルカン同盟諸国がオスマン帝国と戦った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200426,"topic":"year-426","title":"第2次バルカン戦争","year":1913,"era":"近代","region":"modern","level":"標準","q":"「第2次バルカン戦争」は何年？","answer":"1913年","aliases":["1913","西暦1913年","西暦1913","AD1913","1913AD","CE1913","1913CE"],"ex":"1913年。領土配分をめぐってブルガリアと周辺国が争った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200427,"topic":"year-427","title":"ヴェルダンの戦い","year":1916,"era":"現代","region":"modern","level":"標準","q":"「ヴェルダンの戦い」は何年？","answer":"1916年","aliases":["1916","西暦1916年","西暦1916","AD1916","1916AD","CE1916","1916CE"],"ex":"1916年。第一次世界大戦の西部戦線で激しい消耗戦となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200428,"topic":"year-428","title":"アメリカの第一次世界大戦参戦","year":1917,"era":"現代","region":"modern","level":"標準","q":"「アメリカの第一次世界大戦参戦」は何年？","answer":"1917年","aliases":["1917","西暦1917年","西暦1917","AD1917","1917AD","CE1917","1917CE"],"ex":"1917年。無制限潜水艦作戦などを背景に連合国側で参戦した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200429,"topic":"year-429","title":"第一次世界大戦の休戦","year":1918,"era":"現代","region":"modern","level":"標準","q":"「第一次世界大戦の休戦」は何年？","answer":"1918年","aliases":["1918","西暦1918年","西暦1918","AD1918","1918AD","CE1918","1918CE"],"ex":"1918年。ドイツが休戦協定に署名し、西部戦線の戦闘が止まった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200430,"topic":"year-430","title":"ブレスト＝リトフスク条約","year":1918,"era":"現代","region":"modern","level":"標準","q":"「ブレスト＝リトフスク条約」は何年？","answer":"1918年","aliases":["1918","西暦1918年","西暦1918","AD1918","1918AD","CE1918","1918CE"],"ex":"1918年。ソヴィエト政権がドイツなどと単独講和した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200431,"topic":"year-431","title":"ヴェルサイユ条約の調印","year":1919,"era":"現代","region":"modern","level":"標準","q":"「ヴェルサイユ条約の調印」は何年？","answer":"1919年","aliases":["1919","西暦1919年","西暦1919","AD1919","1919AD","CE1919","1919CE"],"ex":"1919年。ドイツに賠償・軍備制限などが課された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200432,"topic":"year-432","title":"朝鮮の三・一独立運動","year":1919,"era":"現代","region":"modern","level":"標準","q":"「朝鮮の三・一独立運動」は何年？","answer":"1919年","aliases":["1919","西暦1919年","西暦1919","AD1919","1919AD","CE1919","1919CE"],"ex":"1919年。日本の植民地支配に対する大規模な独立運動が起きた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200433,"topic":"year-433","title":"国際連盟の発足","year":1920,"era":"現代","region":"modern","level":"標準","q":"「国際連盟の発足」は何年？","answer":"1920年","aliases":["1920","西暦1920年","西暦1920","AD1920","1920AD","CE1920","1920CE"],"ex":"1920年。第一次世界大戦後の集団安全保障をめざした。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200434,"topic":"year-434","title":"ワシントン会議の開会","year":1921,"era":"現代","region":"modern","level":"標準","q":"「ワシントン会議の開会」は何年？","answer":"1921年","aliases":["1921","西暦1921年","西暦1921","AD1921","1921AD","CE1921","1921CE"],"ex":"1921年。海軍軍縮とアジア太平洋の国際秩序が討議された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200435,"topic":"year-435","title":"ソヴィエト社会主義共和国連邦の成立","year":1922,"era":"現代","region":"modern","level":"標準","q":"「ソヴィエト社会主義共和国連邦の成立」は何年？","answer":"1922年","aliases":["1922","西暦1922年","西暦1922","AD1922","1922AD","CE1922","1922CE"],"ex":"1922年。ロシアなどの共和国が連邦を結成した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200436,"topic":"year-436","title":"ムッソリーニの政権獲得","year":1922,"era":"現代","region":"modern","level":"標準","q":"「ムッソリーニの政権獲得」は何年？","answer":"1922年","aliases":["1922","西暦1922年","西暦1922","AD1922","1922AD","CE1922","1922CE"],"ex":"1922年。ローマ進軍を背景に首相に任命された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200437,"topic":"year-437","title":"関東大震災","year":1923,"era":"現代","region":"modern","level":"標準","q":"「関東大震災」は何年？","answer":"1923年","aliases":["1923","西暦1923年","西暦1923","AD1923","1923AD","CE1923","1923CE"],"ex":"1923年。日本の都市社会と経済に甚大な影響を与えた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200438,"topic":"year-438","title":"ドーズ案の採用","year":1924,"era":"現代","region":"modern","level":"標準","q":"「ドーズ案の採用」は何年？","answer":"1924年","aliases":["1924","西暦1924年","西暦1924","AD1924","1924AD","CE1924","1924CE"],"ex":"1924年。ドイツ賠償支払いと経済再建を調整した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200439,"topic":"year-439","title":"ロカルノ条約の調印","year":1925,"era":"現代","region":"modern","level":"標準","q":"「ロカルノ条約の調印」は何年？","answer":"1925年","aliases":["1925","西暦1925年","西暦1925","AD1925","1925AD","CE1925","1925CE"],"ex":"1925年。西欧での国境保障などを通じ協調外交が進んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200440,"topic":"year-440","title":"不戦条約の調印","year":1928,"era":"現代","region":"modern","level":"標準","q":"「不戦条約の調印」は何年？","answer":"1928年","aliases":["1928","西暦1928年","西暦1928","AD1928","1928AD","CE1928","1928CE"],"ex":"1928年。戦争放棄を掲げたが、実効的な制裁手段に課題を残した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200441,"topic":"year-441","title":"世界恐慌の始まり","year":1929,"era":"現代","region":"modern","level":"標準","q":"「世界恐慌の始まり」は何年？","answer":"1929年","aliases":["1929","西暦1929年","西暦1929","AD1929","1929AD","CE1929","1929CE"],"ex":"1929年。ニューヨーク株価暴落を画期に、世界的な不況が深刻化した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200442,"topic":"year-442","title":"ヒトラーの首相就任","year":1933,"era":"現代","region":"modern","level":"標準","q":"「ヒトラーの首相就任」は何年？","answer":"1933年","aliases":["1933","西暦1933年","西暦1933","AD1933","1933AD","CE1933","1933CE"],"ex":"1933年。ナチ党が権力を掌握し、独裁体制を築いた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200443,"topic":"year-443","title":"ローズヴェルトのニューディール開始","year":1933,"era":"現代","region":"modern","level":"標準","q":"「ローズヴェルトのニューディール開始」は何年？","answer":"1933年","aliases":["1933","西暦1933年","西暦1933","AD1933","1933AD","CE1933","1933CE"],"ex":"1933年。アメリカで恐慌への政府の積極的対応が進んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200444,"topic":"year-444","title":"イタリアのエチオピア侵攻","year":1935,"era":"現代","region":"modern","level":"標準","q":"「イタリアのエチオピア侵攻」は何年？","answer":"1935年","aliases":["1935","西暦1935年","西暦1935","AD1935","1935AD","CE1935","1935CE"],"ex":"1935年。国際連盟の集団安全保障体制の弱さが露呈した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200445,"topic":"year-445","title":"スペイン内戦の開始","year":1936,"era":"現代","region":"modern","level":"標準","q":"「スペイン内戦の開始」は何年？","answer":"1936年","aliases":["1936","西暦1936年","西暦1936","AD1936","1936AD","CE1936","1936CE"],"ex":"1936年。反乱軍と共和国側が戦い、独伊などが介入した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200446,"topic":"year-446","title":"ドイツのラインラント進駐","year":1936,"era":"現代","region":"modern","level":"標準","q":"「ドイツのラインラント進駐」は何年？","answer":"1936年","aliases":["1936","西暦1936年","西暦1936","AD1936","1936AD","CE1936","1936CE"],"ex":"1936年。条約に反し非武装地帯へ軍を進めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200447,"topic":"year-447","title":"ミュンヘン会談","year":1938,"era":"現代","region":"modern","level":"標準","q":"「ミュンヘン会談」は何年？","answer":"1938年","aliases":["1938","西暦1938年","西暦1938","AD1938","1938AD","CE1938","1938CE"],"ex":"1938年。英仏がドイツのズデーテン地方併合要求を受け入れた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200448,"topic":"year-448","title":"ドイツによるオーストリア併合","year":1938,"era":"現代","region":"modern","level":"標準","q":"「ドイツによるオーストリア併合」は何年？","answer":"1938年","aliases":["1938","西暦1938年","西暦1938","AD1938","1938AD","CE1938","1938CE"],"ex":"1938年。アンシュルスと呼ばれ、ナチスの勢力拡大が進んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200449,"topic":"year-449","title":"独ソ不可侵条約","year":1939,"era":"現代","region":"modern","level":"標準","q":"「独ソ不可侵条約」は何年？","answer":"1939年","aliases":["1939","西暦1939年","西暦1939","AD1939","1939AD","CE1939","1939CE"],"ex":"1939年。両国が不可侵を約し、秘密議定書で東欧の勢力圏を分けた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200450,"topic":"year-450","title":"日独伊三国同盟","year":1940,"era":"現代","region":"modern","level":"標準","q":"「日独伊三国同盟」は何年？","answer":"1940年","aliases":["1940","西暦1940年","西暦1940","AD1940","1940AD","CE1940","1940CE"],"ex":"1940年。第二次世界大戦期の枢軸側の協力関係を定めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200451,"topic":"year-451","title":"独ソ戦の開始","year":1941,"era":"現代","region":"modern","level":"標準","q":"「独ソ戦の開始」は何年？","answer":"1941年","aliases":["1941","西暦1941年","西暦1941","AD1941","1941AD","CE1941","1941CE"],"ex":"1941年。ドイツがソ連に侵攻し、東部戦線が開かれた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200452,"topic":"year-452","title":"太平洋戦争の開始","year":1941,"era":"現代","region":"modern","level":"標準","q":"「太平洋戦争の開始」は何年？","answer":"1941年","aliases":["1941","西暦1941年","西暦1941","AD1941","1941AD","CE1941","1941CE"],"ex":"1941年。日本の真珠湾攻撃や東南アジアへの進攻で戦争が拡大した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200453,"topic":"year-453","title":"ミッドウェー海戦","year":1942,"era":"現代","region":"modern","level":"標準","q":"「ミッドウェー海戦」は何年？","answer":"1942年","aliases":["1942","西暦1942年","西暦1942","AD1942","1942AD","CE1942","1942CE"],"ex":"1942年。アメリカ軍の勝利が太平洋戦争の重要な転機となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200454,"topic":"year-454","title":"スターリングラードの戦いの終結","year":1943,"era":"現代","region":"modern","level":"標準","q":"「スターリングラードの戦いの終結」は何年？","answer":"1943年","aliases":["1943","西暦1943年","西暦1943","AD1943","1943AD","CE1943","1943CE"],"ex":"1943年。ドイツ軍が降伏し、独ソ戦の流れが変わった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200455,"topic":"year-455","title":"カイロ宣言","year":1943,"era":"現代","region":"modern","level":"標準","q":"「カイロ宣言」は何年？","answer":"1943年","aliases":["1943","西暦1943年","西暦1943","AD1943","1943AD","CE1943","1943CE"],"ex":"1943年。連合国が日本の領土処理などについて方針を示した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200456,"topic":"year-456","title":"ノルマンディー上陸作戦","year":1944,"era":"現代","region":"modern","level":"標準","q":"「ノルマンディー上陸作戦」は何年？","answer":"1944年","aliases":["1944","西暦1944年","西暦1944","AD1944","1944AD","CE1944","1944CE"],"ex":"1944年。連合国軍が西欧に大規模な戦線を開いた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200457,"topic":"year-457","title":"ブレトン＝ウッズ会議","year":1944,"era":"現代","region":"modern","level":"標準","q":"「ブレトン＝ウッズ会議」は何年？","answer":"1944年","aliases":["1944","西暦1944年","西暦1944","AD1944","1944AD","CE1944","1944CE"],"ex":"1944年。戦後の通貨・金融体制の枠組みを定めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200458,"topic":"year-458","title":"ヤルタ会談","year":1945,"era":"現代","region":"modern","level":"標準","q":"「ヤルタ会談」は何年？","answer":"1945年","aliases":["1945","西暦1945年","西暦1945","AD1945","1945AD","CE1945","1945CE"],"ex":"1945年。米英ソ首脳が戦後処理やソ連の対日参戦などを協議した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200459,"topic":"year-459","title":"ポツダム宣言","year":1945,"era":"現代","region":"modern","level":"標準","q":"「ポツダム宣言」は何年？","answer":"1945年","aliases":["1945","西暦1945年","西暦1945","AD1945","1945AD","CE1945","1945CE"],"ex":"1945年。米英中が日本に降伏を求め、のちソ連も参加した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200460,"topic":"year-460","title":"チャーチルの「鉄のカーテン」演説","year":1946,"era":"現代","region":"contemporary","level":"標準","q":"「チャーチルの「鉄のカーテン」演説」は何年？","answer":"1946年","aliases":["1946","西暦1946年","西暦1946","AD1946","1946AD","CE1946","1946CE"],"ex":"1946年。東西対立が深まる状況を表現した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200461,"topic":"year-461","title":"トルーマン＝ドクトリン","year":1947,"era":"現代","region":"contemporary","level":"標準","q":"「トルーマン＝ドクトリン」は何年？","answer":"1947年","aliases":["1947","西暦1947年","西暦1947","AD1947","1947AD","CE1947","1947CE"],"ex":"1947年。アメリカが封じ込め政策の方針を示した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200462,"topic":"year-462","title":"マーシャル＝プランの提唱","year":1947,"era":"現代","region":"contemporary","level":"標準","q":"「マーシャル＝プランの提唱」は何年？","answer":"1947年","aliases":["1947","西暦1947年","西暦1947","AD1947","1947AD","CE1947","1947CE"],"ex":"1947年。西欧の復興援助を通じ、経済再建と共産主義拡大阻止を図った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200463,"topic":"year-463","title":"ベルリン封鎖の開始","year":1948,"era":"現代","region":"contemporary","level":"標準","q":"「ベルリン封鎖の開始」は何年？","answer":"1948年","aliases":["1948","西暦1948年","西暦1948","AD1948","1948AD","CE1948","1948CE"],"ex":"1948年。ソ連の封鎖に対し、西側は空輸で対応した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200464,"topic":"year-464","title":"イスラエル建国","year":1948,"era":"現代","region":"contemporary","level":"標準","q":"「イスラエル建国」は何年？","answer":"1948年","aliases":["1948","西暦1948年","西暦1948","AD1948","1948AD","CE1948","1948CE"],"ex":"1948年。パレスチナ問題と第1次中東戦争を結びつける。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200465,"topic":"year-465","title":"NATOの成立","year":1949,"era":"現代","region":"contemporary","level":"標準","q":"「NATOの成立」は何年？","answer":"1949年","aliases":["1949","西暦1949年","西暦1949","AD1949","1949AD","CE1949","1949CE"],"ex":"1949年。アメリカと西欧諸国などが集団防衛機構を結成した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200466,"topic":"year-466","title":"ドイツ連邦共和国とドイツ民主共和国の成立","year":1949,"era":"現代","region":"contemporary","level":"標準","q":"「ドイツ連邦共和国とドイツ民主共和国の成立」は何年？","answer":"1949年","aliases":["1949","西暦1949年","西暦1949","AD1949","1949AD","CE1949","1949CE"],"ex":"1949年。東西ドイツの分断国家体制が成立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200467,"topic":"year-467","title":"サンフランシスコ平和条約の調印","year":1951,"era":"現代","region":"contemporary","level":"標準","q":"「サンフランシスコ平和条約の調印」は何年？","answer":"1951年","aliases":["1951","西暦1951年","西暦1951","AD1951","1951AD","CE1951","1951CE"],"ex":"1951年。日本の主権回復は翌1952年の発効による。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200468,"topic":"year-468","title":"サンフランシスコ平和条約の発効","year":1952,"era":"現代","region":"contemporary","level":"標準","q":"「サンフランシスコ平和条約の発効」は何年？","answer":"1952年","aliases":["1952","西暦1952年","西暦1952","AD1952","1952AD","CE1952","1952CE"],"ex":"1952年。日本が主権を回復し、占領が終わった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200469,"topic":"year-469","title":"スターリンの死","year":1953,"era":"現代","region":"contemporary","level":"標準","q":"「スターリンの死」は何年？","answer":"1953年","aliases":["1953","西暦1953年","西暦1953","AD1953","1953AD","CE1953","1953CE"],"ex":"1953年。ソ連・東欧と国際関係の転換点となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200470,"topic":"year-470","title":"ワルシャワ条約機構の成立","year":1955,"era":"現代","region":"contemporary","level":"標準","q":"「ワルシャワ条約機構の成立」は何年？","answer":"1955年","aliases":["1955","西暦1955年","西暦1955","AD1955","1955AD","CE1955","1955CE"],"ex":"1955年。ソ連と東欧諸国が軍事同盟を結成した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200471,"topic":"year-471","title":"フルシチョフのスターリン批判","year":1956,"era":"現代","region":"contemporary","level":"標準","q":"「フルシチョフのスターリン批判」は何年？","answer":"1956年","aliases":["1956","西暦1956年","西暦1956","AD1956","1956AD","CE1956","1956CE"],"ex":"1956年。ソ連共産党第20回大会で個人崇拝などを批判した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200472,"topic":"year-472","title":"ハンガリー動乱","year":1956,"era":"現代","region":"contemporary","level":"標準","q":"「ハンガリー動乱」は何年？","answer":"1956年","aliases":["1956","西暦1956年","西暦1956","AD1956","1956AD","CE1956","1956CE"],"ex":"1956年。改革を求める運動にソ連軍が介入した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200473,"topic":"year-473","title":"スエズ戦争（第2次中東戦争）","year":1956,"era":"現代","region":"contemporary","level":"標準","q":"「スエズ戦争（第2次中東戦争）」は何年？","answer":"1956年","aliases":["1956","西暦1956年","西暦1956","AD1956","1956AD","CE1956","1956CE"],"ex":"1956年。ナセルの運河国有化を背景に英仏・イスラエルが軍事行動した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200474,"topic":"year-474","title":"ローマ条約の調印","year":1957,"era":"現代","region":"contemporary","level":"標準","q":"「ローマ条約の調印」は何年？","answer":"1957年","aliases":["1957","西暦1957年","西暦1957","AD1957","1957AD","CE1957","1957CE"],"ex":"1957年。EECとユーラトムの設立を定め、翌年発効した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200475,"topic":"year-475","title":"キューバ革命","year":1959,"era":"現代","region":"contemporary","level":"標準","q":"「キューバ革命」は何年？","answer":"1959年","aliases":["1959","西暦1959年","西暦1959","AD1959","1959AD","CE1959","1959CE"],"ex":"1959年。カストロらがバティスタ政権を倒した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200476,"topic":"year-476","title":"「アフリカの年」","year":1960,"era":"現代","region":"contemporary","level":"標準","q":"「「アフリカの年」」は何年？","answer":"1960年","aliases":["1960","西暦1960年","西暦1960","AD1960","1960AD","CE1960","1960CE"],"ex":"1960年。アフリカで17か国が独立し、脱植民地化が進んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200477,"topic":"year-477","title":"ベルリンの壁の建設","year":1961,"era":"現代","region":"contemporary","level":"標準","q":"「ベルリンの壁の建設」は何年？","answer":"1961年","aliases":["1961","西暦1961年","西暦1961","AD1961","1961AD","CE1961","1961CE"],"ex":"1961年。東ドイツから西側への人口流出を阻止しようとした。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200478,"topic":"year-478","title":"第1回非同盟諸国首脳会議","year":1961,"era":"現代","region":"contemporary","level":"標準","q":"「第1回非同盟諸国首脳会議」は何年？","answer":"1961年","aliases":["1961","西暦1961年","西暦1961","AD1961","1961AD","CE1961","1961CE"],"ex":"1961年。ベオグラードで開かれ、東西両陣営への非同盟を掲げた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200479,"topic":"year-479","title":"キューバ危機","year":1962,"era":"現代","region":"contemporary","level":"標準","q":"「キューバ危機」は何年？","answer":"1962年","aliases":["1962","西暦1962年","西暦1962","AD1962","1962AD","CE1962","1962CE"],"ex":"1962年。米ソが核戦争の危険を伴う対立に至った。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200480,"topic":"year-480","title":"アルジェリア独立","year":1962,"era":"現代","region":"contemporary","level":"標準","q":"「アルジェリア独立」は何年？","answer":"1962年","aliases":["1962","西暦1962年","西暦1962","AD1962","1962AD","CE1962","1962CE"],"ex":"1962年。フランスとの長い独立戦争を経て実現した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200481,"topic":"year-481","title":"部分的核実験禁止条約の調印","year":1963,"era":"現代","region":"contemporary","level":"標準","q":"「部分的核実験禁止条約の調印」は何年？","answer":"1963年","aliases":["1963","西暦1963年","西暦1963","AD1963","1963AD","CE1963","1963CE"],"ex":"1963年。大気圏内・宇宙空間・水中での核実験を禁止した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200482,"topic":"year-482","title":"アメリカ公民権法の成立","year":1964,"era":"現代","region":"contemporary","level":"標準","q":"「アメリカ公民権法の成立」は何年？","answer":"1964年","aliases":["1964","西暦1964年","西暦1964","AD1964","1964AD","CE1964","1964CE"],"ex":"1964年。人種などによる差別を禁止する画期となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200483,"topic":"year-483","title":"第3次中東戦争","year":1967,"era":"現代","region":"contemporary","level":"標準","q":"「第3次中東戦争」は何年？","answer":"1967年","aliases":["1967","西暦1967年","西暦1967","AD1967","1967AD","CE1967","1967CE"],"ex":"1967年。イスラエルが西岸地区・ガザ地区などを占領した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200484,"topic":"year-484","title":"プラハの春と軍事介入","year":1968,"era":"現代","region":"contemporary","level":"標準","q":"「プラハの春と軍事介入」は何年？","answer":"1968年","aliases":["1968","西暦1968年","西暦1968","AD1968","1968AD","CE1968","1968CE"],"ex":"1968年。チェコスロヴァキアの改革運動がワルシャワ条約機構軍に抑えられた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200485,"topic":"year-485","title":"核拡散防止条約の署名開放","year":1968,"era":"現代","region":"contemporary","level":"標準","q":"「核拡散防止条約の署名開放」は何年？","answer":"1968年","aliases":["1968","西暦1968年","西暦1968","AD1968","1968AD","CE1968","1968CE"],"ex":"1968年。核保有国の拡散防止などを掲げ、1970年に発効した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200486,"topic":"year-486","title":"アポロ11号の月面着陸","year":1969,"era":"現代","region":"contemporary","level":"標準","q":"「アポロ11号の月面着陸」は何年？","answer":"1969年","aliases":["1969","西暦1969年","西暦1969","AD1969","1969AD","CE1969","1969CE"],"ex":"1969年。冷戦下の宇宙開発競争の大きな成果となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200487,"topic":"year-487","title":"ニクソン＝ショック（金とドルの交換停止）","year":1971,"era":"現代","region":"contemporary","level":"標準","q":"「ニクソン＝ショック（金とドルの交換停止）」は何年？","answer":"1971年","aliases":["1971","西暦1971年","西暦1971","AD1971","1971AD","CE1971","1971CE"],"ex":"1971年。ブレトン＝ウッズ体制の転換につながった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200488,"topic":"year-488","title":"SALT Iの調印","year":1972,"era":"現代","region":"contemporary","level":"標準","q":"「SALT Iの調印」は何年？","answer":"1972年","aliases":["1972","西暦1972年","西暦1972","AD1972","1972AD","CE1972","1972CE"],"ex":"1972年。米ソが戦略兵器制限で合意し、緊張緩和が進んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200489,"topic":"year-489","title":"第4次中東戦争と第1次石油危機","year":1973,"era":"現代","region":"contemporary","level":"標準","q":"「第4次中東戦争と第1次石油危機」は何年？","answer":"1973年","aliases":["1973","西暦1973年","西暦1973","AD1973","1973AD","CE1973","1973CE"],"ex":"1973年。産油国の政策が世界経済に大きな影響を与えた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200490,"topic":"year-490","title":"ヘルシンキ宣言","year":1975,"era":"現代","region":"contemporary","level":"標準","q":"「ヘルシンキ宣言」は何年？","answer":"1975年","aliases":["1975","西暦1975年","西暦1975","AD1975","1975AD","CE1975","1975CE"],"ex":"1975年。欧州安全保障協力会議で国境尊重や人権などが確認された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200491,"topic":"year-491","title":"キャンプ＝デーヴィッド合意","year":1978,"era":"現代","region":"contemporary","level":"標準","q":"「キャンプ＝デーヴィッド合意」は何年？","answer":"1978年","aliases":["1978","西暦1978年","西暦1978","AD1978","1978AD","CE1978","1978CE"],"ex":"1978年。エジプトとイスラエルの和平への枠組みがつくられた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200492,"topic":"year-492","title":"ソ連のアフガニスタン侵攻","year":1979,"era":"現代","region":"contemporary","level":"標準","q":"「ソ連のアフガニスタン侵攻」は何年？","answer":"1979年","aliases":["1979","西暦1979年","西暦1979","AD1979","1979AD","CE1979","1979CE"],"ex":"1979年。緊張緩和が後退し、新冷戦と呼ばれる対立が強まった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200493,"topic":"year-493","title":"ポーランドの「連帯」結成","year":1980,"era":"現代","region":"contemporary","level":"標準","q":"「ポーランドの「連帯」結成」は何年？","answer":"1980年","aliases":["1980","西暦1980年","西暦1980","AD1980","1980AD","CE1980","1980CE"],"ex":"1980年。労働組合運動が共産党支配に揺さぶりをかけた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200494,"topic":"year-494","title":"ゴルバチョフのソ連共産党書記長就任","year":1985,"era":"現代","region":"contemporary","level":"標準","q":"「ゴルバチョフのソ連共産党書記長就任」は何年？","answer":"1985年","aliases":["1985","西暦1985年","西暦1985","AD1985","1985AD","CE1985","1985CE"],"ex":"1985年。ペレストロイカとグラスノスが進められた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200495,"topic":"year-495","title":"マルタ会談","year":1989,"era":"現代","region":"contemporary","level":"標準","q":"「マルタ会談」は何年？","answer":"1989年","aliases":["1989","西暦1989年","西暦1989","AD1989","1989AD","CE1989","1989CE"],"ex":"1989年。米ソ首脳が冷戦終結に向かう関係改善を確認した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200496,"topic":"year-496","title":"ドイツ統一","year":1990,"era":"現代","region":"contemporary","level":"標準","q":"「ドイツ統一」は何年？","answer":"1990年","aliases":["1990","西暦1990年","西暦1990","AD1990","1990AD","CE1990","1990CE"],"ex":"1990年。東ドイツが西ドイツへ編入される形で統一した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200497,"topic":"year-497","title":"湾岸戦争","year":1991,"era":"現代","region":"contemporary","level":"標準","q":"「湾岸戦争」は何年？","answer":"1991年","aliases":["1991","西暦1991年","西暦1991","AD1991","1991AD","CE1991","1991CE"],"ex":"1991年。イラクのクウェート侵攻に対し、多国籍軍が軍事行動した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200498,"topic":"year-498","title":"ソ連の解体","year":1991,"era":"現代","region":"contemporary","level":"標準","q":"「ソ連の解体」は何年？","answer":"1991年","aliases":["1991","西暦1991年","西暦1991","AD1991","1991AD","CE1991","1991CE"],"ex":"1991年。共和国の独立が進み、ソヴィエト連邦が消滅した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200499,"topic":"year-499","title":"マーストリヒト条約の調印","year":1992,"era":"現代","region":"contemporary","level":"標準","q":"「マーストリヒト条約の調印」は何年？","answer":"1992年","aliases":["1992","西暦1992年","西暦1992","AD1992","1992AD","CE1992","1992CE"],"ex":"1992年。欧州連合創設を定め、翌1993年に発効した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200500,"topic":"year-500","title":"欧州連合（EU）の発足","year":1993,"era":"現代","region":"contemporary","level":"標準","q":"「欧州連合（EU）の発足」は何年？","answer":"1993年","aliases":["1993","西暦1993年","西暦1993","AD1993","1993AD","CE1993","1993CE"],"ex":"1993年。マーストリヒト条約の発効により成立した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200501,"topic":"year-501","title":"オスロ合意","year":1993,"era":"現代","region":"contemporary","level":"標準","q":"「オスロ合意」は何年？","answer":"1993年","aliases":["1993","西暦1993年","西暦1993","AD1993","1993AD","CE1993","1993CE"],"ex":"1993年。イスラエルとPLOが相互承認と暫定自治に合意した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200502,"topic":"year-502","title":"南アフリカの全人種参加選挙","year":1994,"era":"現代","region":"contemporary","level":"標準","q":"「南アフリカの全人種参加選挙」は何年？","answer":"1994年","aliases":["1994","西暦1994年","西暦1994","AD1994","1994AD","CE1994","1994CE"],"ex":"1994年。マンデラが大統領となり、アパルトヘイト後の体制が始まった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200503,"topic":"year-503","title":"世界貿易機関（WTO）の発足","year":1995,"era":"現代","region":"contemporary","level":"標準","q":"「世界貿易機関（WTO）の発足」は何年？","answer":"1995年","aliases":["1995","西暦1995年","西暦1995","AD1995","1995AD","CE1995","1995CE"],"ex":"1995年。GATTを継承し、国際貿易の制度を拡充した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200504,"topic":"year-504","title":"ユーロの導入（非現金決済）","year":1999,"era":"現代","region":"contemporary","level":"発展","q":"「ユーロの導入（非現金決済）」は何年？","answer":"1999年","aliases":["1999","西暦1999年","西暦1999","AD1999","1999AD","CE1999","1999CE"],"ex":"1999年。ユーロ紙幣・硬貨の流通開始は2002年。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200505,"topic":"year-505","title":"アメリカ同時多発テロ","year":2001,"era":"現代","region":"contemporary","level":"標準","q":"「アメリカ同時多発テロ」は何年？","answer":"2001年","aliases":["2001","西暦2001年","西暦2001","AD2001","2001AD","CE2001","2001CE"],"ex":"2001年。アフガニスタン戦争など、対テロ戦争の拡大につながった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200506,"topic":"year-506","title":"ユーロ紙幣・硬貨の流通開始","year":2002,"era":"現代","region":"contemporary","level":"標準","q":"「ユーロ紙幣・硬貨の流通開始」は何年？","answer":"2002年","aliases":["2002","西暦2002年","西暦2002","AD2002","2002AD","CE2002","2002CE"],"ex":"2002年。1999年の非現金通貨としての導入と区別する。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200507,"topic":"year-507","title":"イラク戦争の開始","year":2003,"era":"現代","region":"contemporary","level":"標準","q":"「イラク戦争の開始」は何年？","answer":"2003年","aliases":["2003","西暦2003年","西暦2003","AD2003","2003AD","CE2003","2003CE"],"ex":"2003年。米英などがイラクへ侵攻し、フセイン政権が崩壊した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200508,"topic":"year-508","title":"リーマン＝ブラザーズの破綻","year":2008,"era":"現代","region":"contemporary","level":"標準","q":"「リーマン＝ブラザーズの破綻」は何年？","answer":"2008年","aliases":["2008","西暦2008年","西暦2008","AD2008","2008AD","CE2008","2008CE"],"ex":"2008年。世界金融危機の深刻化を象徴した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200509,"topic":"year-509","title":"エジプトのムバラク政権崩壊","year":2011,"era":"現代","region":"contemporary","level":"標準","q":"「エジプトのムバラク政権崩壊」は何年？","answer":"2011年","aliases":["2011","西暦2011年","西暦2011","AD2011","2011AD","CE2011","2011CE"],"ex":"2011年。「アラブの春」と呼ばれる政治変動の一部。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200510,"topic":"year-510","title":"パリ協定の採択","year":2015,"era":"現代","region":"contemporary","level":"標準","q":"「パリ協定の採択」は何年？","answer":"2015年","aliases":["2015","西暦2015年","西暦2015","AD2015","2015AD","CE2015","2015CE"],"ex":"2015年。気候変動への国際的な対応枠組みを定めた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200511,"topic":"year-511","title":"グーテンベルクの聖書印刷完成の一般的な年代","year":1455,"era":"中世","region":"culture","level":"発展","q":"「グーテンベルクの聖書印刷完成の一般的な年代」は何年？","answer":"1455年","aliases":["1455","西暦1455年","西暦1455","AD1455","1455AD","CE1455","1455CE"],"ex":"1455年。西欧の活版印刷の発達が知識の流通を広げた。1450年代の事業としても整理する。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第1巻","url":"https://openstax.org/details/books/world-history-volume-1"}]},{"id":200512,"topic":"year-512","title":"トマス＝モア『ユートピア』刊行","year":1516,"era":"近世","region":"culture","level":"標準","q":"「トマス＝モア『ユートピア』刊行」は何年？","answer":"1516年","aliases":["1516","西暦1516年","西暦1516","AD1516","1516AD","CE1516","1516CE"],"ex":"1516年。社会批判を理想の島の叙述に託した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200513,"topic":"year-513","title":"マキァヴェリ『君主論』初刊","year":1532,"era":"近世","region":"culture","level":"標準","q":"「マキァヴェリ『君主論』初刊」は何年？","answer":"1532年","aliases":["1532","西暦1532年","西暦1532","AD1532","1532AD","CE1532","1532CE"],"ex":"1532年。執筆は1513年頃で、死後に出版された。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200514,"topic":"year-514","title":"ガリレイ『天文対話』刊行","year":1632,"era":"近世","region":"culture","level":"標準","q":"「ガリレイ『天文対話』刊行」は何年？","answer":"1632年","aliases":["1632","西暦1632年","西暦1632","AD1632","1632AD","CE1632","1632CE"],"ex":"1632年。地動説をめぐる議論と宗教裁判を結びつける。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200515,"topic":"year-515","title":"デカルト『方法序説』刊行","year":1637,"era":"近世","region":"culture","level":"標準","q":"「デカルト『方法序説』刊行」は何年？","answer":"1637年","aliases":["1637","西暦1637年","西暦1637","AD1637","1637AD","CE1637","1637CE"],"ex":"1637年。近代合理主義の代表的な著作。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200516,"topic":"year-516","title":"ホッブズ『リヴァイアサン』刊行","year":1651,"era":"近世","region":"culture","level":"標準","q":"「ホッブズ『リヴァイアサン』刊行」は何年？","answer":"1651年","aliases":["1651","西暦1651年","西暦1651","AD1651","1651AD","CE1651","1651CE"],"ex":"1651年。社会契約と強い主権国家の必要を論じた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200517,"topic":"year-517","title":"ロック『統治二論』の標題紙の年","year":1690,"era":"近世","region":"culture","level":"発展","q":"「ロック『統治二論』の標題紙の年」は何年？","answer":"1690年","aliases":["1690","西暦1690年","西暦1690","AD1690","1690AD","CE1690","1690CE"],"ex":"1690年。実際には1689年末に刊行。抵抗権や立憲政治の理論と結びつける。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200518,"topic":"year-518","title":"モンテスキュー『法の精神』刊行","year":1748,"era":"近世","region":"culture","level":"標準","q":"「モンテスキュー『法の精神』刊行」は何年？","answer":"1748年","aliases":["1748","西暦1748年","西暦1748","AD1748","1748AD","CE1748","1748CE"],"ex":"1748年。権力の分立と政治制度を論じた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200519,"topic":"year-519","title":"フランス『百科全書』第1巻刊行","year":1751,"era":"近世","region":"culture","level":"標準","q":"「フランス『百科全書』第1巻刊行」は何年？","answer":"1751年","aliases":["1751","西暦1751年","西暦1751","AD1751","1751AD","CE1751","1751CE"],"ex":"1751年。ディドロらが知識を体系化し、啓蒙思想を広げた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200520,"topic":"year-520","title":"ルソー『社会契約論』刊行","year":1762,"era":"近世","region":"culture","level":"標準","q":"「ルソー『社会契約論』刊行」は何年？","answer":"1762年","aliases":["1762","西暦1762年","西暦1762","AD1762","1762AD","CE1762","1762CE"],"ex":"1762年。人民主権と一般意志を論じた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200521,"topic":"year-521","title":"アダム＝スミス『国富論』刊行","year":1776,"era":"近世","region":"culture","level":"標準","q":"「アダム＝スミス『国富論』刊行」は何年？","answer":"1776年","aliases":["1776","西暦1776年","西暦1776","AD1776","1776AD","CE1776","1776CE"],"ex":"1776年。分業と市場の働きを論じた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200522,"topic":"year-522","title":"カント『純粋理性批判』初版刊行","year":1781,"era":"近世","region":"culture","level":"発展","q":"「カント『純粋理性批判』初版刊行」は何年？","answer":"1781年","aliases":["1781","西暦1781年","西暦1781","AD1781","1781AD","CE1781","1781CE"],"ex":"1781年。人間の認識が可能となる条件を問うた。","difficulty":"発展","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200523,"topic":"year-523","title":"ジェンナーの種痘実験","year":1796,"era":"近世","region":"culture","level":"標準","q":"「ジェンナーの種痘実験」は何年？","answer":"1796年","aliases":["1796","西暦1796年","西暦1796","AD1796","1796AD","CE1796","1796CE"],"ex":"1796年。天然痘予防の発達に重要な役割を果たした。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200524,"topic":"year-524","title":"マルクスとエンゲルス『共産党宣言』刊行","year":1848,"era":"近代","region":"culture","level":"標準","q":"「マルクスとエンゲルス『共産党宣言』刊行」は何年？","answer":"1848年","aliases":["1848","西暦1848年","西暦1848","AD1848","1848AD","CE1848","1848CE"],"ex":"1848年。階級闘争と共産主義運動の綱領を示した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200525,"topic":"year-525","title":"ダーウィン『種の起源』刊行","year":1859,"era":"近代","region":"culture","level":"標準","q":"「ダーウィン『種の起源』刊行」は何年？","answer":"1859年","aliases":["1859","西暦1859年","西暦1859","AD1859","1859AD","CE1859","1859CE"],"ex":"1859年。自然選択による生物進化の理論を提示した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200526,"topic":"year-526","title":"マルクス『資本論』第1巻刊行","year":1867,"era":"近代","region":"culture","level":"標準","q":"「マルクス『資本論』第1巻刊行」は何年？","answer":"1867年","aliases":["1867","西暦1867年","西暦1867","AD1867","1867AD","CE1867","1867CE"],"ex":"1867年。資本主義の生産と経済構造を分析した。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200527,"topic":"year-527","title":"ベルの電話特許取得","year":1876,"era":"近代","region":"culture","level":"標準","q":"「ベルの電話特許取得」は何年？","answer":"1876年","aliases":["1876","西暦1876年","西暦1876","AD1876","1876AD","CE1876","1876CE"],"ex":"1876年。通信技術の発達を示す出来事のひとつ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200528,"topic":"year-528","title":"レントゲンのX線発見","year":1895,"era":"近代","region":"culture","level":"標準","q":"「レントゲンのX線発見」は何年？","answer":"1895年","aliases":["1895","西暦1895年","西暦1895","AD1895","1895AD","CE1895","1895CE"],"ex":"1895年。医学や物理学に大きな影響を与えた。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200529,"topic":"year-529","title":"アインシュタインの特殊相対性理論の論文発表","year":1905,"era":"近代","region":"culture","level":"標準","q":"「アインシュタインの特殊相対性理論の論文発表」は何年？","answer":"1905年","aliases":["1905","西暦1905年","西暦1905","AD1905","1905AD","CE1905","1905CE"],"ex":"1905年。光と時空に関する新たな物理学が進んだ。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200530,"topic":"year-530","title":"フレミングのペニシリン発見","year":1928,"era":"現代","region":"culture","level":"標準","q":"「フレミングのペニシリン発見」は何年？","answer":"1928年","aliases":["1928","西暦1928年","西暦1928","AD1928","1928AD","CE1928","1928CE"],"ex":"1928年。抗生物質の開発へつながる発見となった。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]},{"id":200531,"topic":"year-531","title":"DNA二重らせん構造のモデル発表","year":1953,"era":"現代","region":"culture","level":"標準","q":"「DNA二重らせん構造のモデル発表」は何年？","answer":"1953年","aliases":["1953","西暦1953年","西暦1953","AD1953","1953AD","CE1953","1953CE"],"ex":"1953年。ワトソンとクリックらの研究。フランクリンらの実験的貢献も重要。","difficulty":"標準","yearQuiz":true,"refs":[{"label":"時代背景を読む · OpenStax 世界史 第2巻","url":"https://openstax.org/details/books/world-history-volume-2"}]}];
